# --- 输出:去心跳帧 + 打码 + 同时落盘 ---------------------------------------
redact() {
  # 控制台丢字会把一行拆开,所以除了 sk- 前缀,任何 24 字符以上的
  # token 样字符串也整体打码,避免半截密钥漏出去。
  sed -E 's/sk-[A-Za-z0-9_-]{4,}/<REDACTED>/g; s/[A-Za-z0-9_-]{24,}/<REDACTED>/g'
}
emit() {
  local line
  line=$(printf '%s' "$1" | redact)
  printf '%s\n' "$line"
  printf '%s\n' "$line" >>"$LOG"
}
say() { printf '%s\n' "$*"; printf '%s\n' "$*" >>"$LOG"; }

