19	/* The AP does not re-run the device bring-up; it sizes its half from the
20	 * same device table bk7258_psram.c probes with.  Both known devices are
21	 * 16MB on this board (APS128XXO); the split halves whatever is present. */
22	#define BK7258_PSRAM_EXPECTED_SIZE \
23	  (16u * 1024u * 1024u)
24	
25	/* Guard this component's RAM window against the cross-domain regions. The
26	 * linker script cannot do this: including the chip header there would drag in
27	 * stdint.h and UINT32_C() suffixes that the linker rejects, so the check lives
28	 * here, next to the code that computes the heap's upper bound.
29	 *
30	 * PWR_MNG is a fixed-address CP/AP ABI and SWAP carries the AP boot record. A
31	 * component whose .data/.bss or heap grew over them would silently corrupt the
32	 * other domain rather than fail to link. Both checks are compile-time only and
33	 * generate no code.
34	 */
35	
36	static_assert(CONFIG_RAM_START >= BK7258_SRAM_CAPACITY_BASE &&
37	              CONFIG_RAM_END <= BK7258_SRAM_CAPACITY_END,
38	              "BK7258 component RAM window falls outside the SoC SRAM");
39	static_assert(CONFIG_RAM_END <= BK7258_PWR_MNG_BASE,
40	              "BK7258 component RAM window overlaps PWR_MNG/SWAP");
41	static_assert(CONFIG_RAM_START >= BK7258_AP_SPINLOCK_BASE +
42	                                  BK7258_AP_SPINLOCK_SIZE,
43	              "BK7258 component RAM window overlaps AP_SPINLOCK");
44	
45	#ifdef CONFIG_BK7258_COMPONENT_AP
46	static_assert(CONFIG_RAM_START == BK7258_AP_RAM_BASE,
47	              "BK7258 AP RAM start differs from the all-OpenVela tuple");
48	static_assert(CONFIG_RAM_SIZE == BK7258_AP_RAM_SIZE,
49	              "BK7258 AP RAM size differs from the all-OpenVela tuple");
50	static_assert(CONFIG_RAM_END == CONFIG_BK7258_RPMSG_SHM_ADDR,
51	              "BK7258 AP RAM must end where RPMSG_SHM begins");
52	#else
53	static_assert(CONFIG_RAM_START == CONFIG_BK7258_RPMSG_SHM_ADDR +
54	                                  CONFIG_BK7258_RPMSG_SHM_SIZE,
55	              "BK7258 CP RAM must begin after RPMSG_SHM");
56	static_assert(CONFIG_RAM_END == BK7258_PWR_MNG_BASE,
57	              "BK7258 CP RAM must end where PWR_MNG begins");
58	#endif
59	
60	const uintptr_t g_idle_topstack =
61	  (uintptr_t)_ebss + CONFIG_IDLETHREAD_STACKSIZE;
62	
63	#ifdef CONFIG_BK7258_COMPONENT_CP
64	static void bk7258_heap_mark_hex(uintptr_t value)
65	{
66	  static const char hex[] = "0123456789ABCDEF";
67	  int shift;
68	
69	  for (shift = (int)(sizeof(value) * 8) - 4; shift >= 0; shift -= 4)
70	    {
71	      bk7258_lowputc(hex[(value >> shift) & 0xf]);
72	    }
73	}
