76	void up_allocate_heap(void **heap_start, size_t *heap_size)
77	{
78	  /* Bound the heap with CONFIG_RAM_END, as the upstream arch allocators do.
79	   * It is derived from this component's own CONFIG_RAM_START/CONFIG_RAM_SIZE,
80	   * so CP and AP each get their configured window with nothing to keep in sync
81	   * by hand, and neither can grow into the cross-domain PWR_MNG/SWAP regions.
82	   */
83	
84	  *heap_start = (void *)g_idle_topstack;
85	  *heap_size = CONFIG_RAM_END - g_idle_topstack;
86	
87	  /* Temporary BK-only allocator evidence. This runs after lowsetup and before
88	   * common driver allocations, so it proves the precise heap handed to the
89	   * first RPMsg UART allocations without requiring syslog or malloc itself. */
90	#ifdef CONFIG_BK7258_COMPONENT_CP
91	  BK7258_BOOT_MARK('H');
92	  bk7258_heap_mark_hex((uintptr_t)*heap_start);
93	  BK7258_BOOT_MARK(':');
94	  bk7258_heap_mark_hex((uintptr_t)*heap_size);
95	  BK7258_BOOT_MARK('\r');
96	  BK7258_BOOT_MARK('\n');
97	#endif
