115	void bk7258_psram_addregion(void)
116	#else
117	void arm_addregion(void)
118	#endif
119	{
120	#ifdef CONFIG_BK7258_PSRAM
121	  size_t psram_size;
122	  uint16_t device_id;
123	  uintptr_t region_base;
124	  size_t region_size;
125	  int ret;
126	
127	  /* Temporary CP-only PSRAM bring-up bracket.  arm_addregion() runs after
128	   * the F timer marker and before serial initialization's G marker, so this
129	   * identifies whether the added external-heap path returns at all. */
130	  BK7258_BOOT_MARK('P');
131	#ifdef CONFIG_BK7258_COMPONENT_AP
132	  /* AP: the CP has already configured the device and the 120MHz clock.  A
133	   * plain read of the device answers only when that bring-up happened; do
134	   * not pattern-write anything (the probe would smash the CP's half). */
135	  {
136	    volatile uint32_t *probe = (volatile uint32_t *)BK7258_PSRAM_BASE;
137	    uint32_t dummy = *probe;
138	
139	    UNUSED(dummy);
140	    psram_size = BK7258_PSRAM_EXPECTED_SIZE;
141	    device_id  = 0;
142	    ret        = OK;
143	  }
144	#else
145	  ret = bk7258_psram_initialize(&psram_size, &device_id);
146	#endif
147	  BK7258_BOOT_MARK('R');
148	  if (ret < 0)
149	    {
150	      syslog(LOG_WARNING,
151	             "[BK7258] PSRAM unavailable (%d); using internal SRAM heap only\n",
152	             ret);
153	      return;
154	    }
155	
156	  /* PSRAM is partitioned the way the authority CSV does it, only sized for
157	   * the 16 MiB APS128XXO on this board: fixed display/audio/encode slabs and a
158	   * .psram section, then one bounded heap per core (bk7258_memorymap.h).  Each
159	   * core adds only its own slab, so the two kernels never allocate from the
160	   * same bytes and os_check_heap_range() can enforce it.
161	   *
162	   * The CP brings the device up first (it boots first).  The AP must not
163	   * re-run the bring-up: bk7258_psram_probe() pattern-writes the first
164	   * CONFIG_BK7258_PSRAM_PROBE_SIZE bytes at the device base -- inside the
165	   * display slab by then -- and the configure/clock sequence is settled.  The
166	   * AP trusts the CP's bring-up, checks that the device answers, and adds only
167	   * its own heap slab. */
168	
169	#if defined(CONFIG_BK7258_COMPONENT_CP)
170	  region_base = BK7258_CP_PSRAM_HEAP_BASE;
171	  region_size = BK7258_CP_PSRAM_HEAP_SIZE;
172	#elif defined(CONFIG_BK7258_COMPONENT_AP)
173	  region_base = BK7258_AP_PSRAM_HEAP_BASE;
174	  region_size = BK7258_AP_PSRAM_HEAP_SIZE;
175	#else
176	#error "PSRAM layout requires a BK7258 component selection (CP or AP)"
177	#endif
178	
179	  /* A layout larger than the fitted device would hand out addresses the part
180	   * does not decode, so refuse it loudly and fall back to the SRAM heap. */
181	
182	  if (region_base + region_size > BK7258_PSRAM_BASE + psram_size)
183	    {
184	      syslog(LOG_ERR,
185	             "[BK7258] PSRAM layout ends at %08lx, device ends at %08lx; "
186	             "heap left on SRAM\n",
187	             (unsigned long)(region_base + region_size),
188	             (unsigned long)(BK7258_PSRAM_BASE + psram_size));
189	      return;
190	    }
191	
192	  kumm_addregion((void *)region_base, region_size);
193	  syslog(LOG_INFO, "[BK7258] PSRAM id=0x%04x size=%lu split: core region "
194	         "%08lx-%08lx added to heap\n",
195	         device_id, (unsigned long)psram_size,
196	         (unsigned long)region_base,
197	         (unsigned long)(region_base + region_size - 1));
198	#endif
199	}
200	#endif
