545	/* Both mutex kinds use a recursive NuttX mutex: a FreeRTOS mutex taken
546	 * twice by its holder deadlocks, which Armino code never relies on.
547	 */
548	
549	QueueHandle_t xQueueCreateMutex(const uint8_t type)
550	{
551	  QueueHandle_t q = kmm_zalloc(sizeof(*q));
552	
553	  if (q != NULL)
554	    {
555	      q->type = type;
556	      nxrmutex_init(&q->u.mutex);
557	    }
558	
559	  return q;
560	}
561	
562	void vQueueDelete(QueueHandle_t q)
563	{
564	  if (q == NULL)
565	    {
566	      return;
567	    }
568	
569	  if (armino_is_semaphore(q))
570	    {
571	      nxsem_destroy(&q->u.sem);
572	    }
573	  else if (armino_is_mutex(q))
574	    {
575	      nxrmutex_destroy(&q->u.mutex);
576	    }
577	  else
578	    {
579	      file_mq_close(&q->u.mq);
580	    }
581	
582	  kmm_free(q);
583	}
584	
585	static BaseType_t armino_sem_give(QueueHandle_t q)
586	{
587	  int value = 0;
588	
589	  nxsem_get_value(&q->u.sem, &value);
590	  if (value >= (int)q->max_count)
591	    {
592	      return errQUEUE_FULL;
593	    }
594	
595	  return nxsem_post(&q->u.sem) == OK ? pdPASS : pdFAIL;
596	}
597	
598	static void armino_queue_hiwater(QueueHandle_t q)
599	{
600	  struct mq_attr attr;
601	
602	  if (file_mq_getattr(&q->u.mq, &attr) == OK && attr.mq_curmsgs > q->hiwater)
603	    {
604	      q->hiwater = attr.mq_curmsgs;
605	      /* Routine fill level is not news: a34-deep queue reporting 2/34 then
606	       * 3/34 then 4/34 floods the console and buries what matters.  Log
607	       * only when the queue actually reaches capacity -- that is the wall
608	       * a caller feels.  hiwater only rises, so this fires once per queue.
609	       */
610	
611	      if ((unsigned long)q->hiwater >= q->depth)
612	        {
613	          syslog(LOG_WARNING, "[ARMINO] queue %u FULL %ld/%lu\n", q->id,
614	                 q->hiwater, (unsigned long)q->depth);
615	        }
616	    }
617	}
618	
619	static BaseType_t armino_queue_send(QueueHandle_t q, const void *item,
620	                                    TickType_t ticks, BaseType_t pos)
621	{
622	  unsigned int prio = pos == queueSEND_TO_FRONT ? 1 : 0;
623	  int ret;
624	
625	  if (pos == queueOVERWRITE)
626	    {
627	      syslog(LOG_ERR, "[ARMINO] queue %u: overwrite unsupported\n", q->id);
628	      return pdFAIL;
629	    }
630	
631	  /* A zero timeout is "try once" in FreeRTOS. NuttX's tick send with 0
632	   * still arms a watchdog and waits for it, so a full queue is answered
633	   * here. ponytail: check and send are not atomic; a slot freed in between
634	   * only costs that one try.
635	   */
636	
637	  if (ticks == 0 && !up_interrupt_context() &&
638	      armino_queue_count(q) >= (long)q->depth)
639	    {
640	      return errQUEUE_FULL;
641	    }
642	
643	  if (ticks == portMAX_DELAY && !up_interrupt_context())
644	    {
645	      ret = file_mq_send(&q->u.mq, item, q->item_size, prio);
646	    }
647	  else
648	    {
649	      ret = file_mq_ticksend(&q->u.mq, item, q->item_size, prio,
650	                             (sclock_t)ticks);
651	    }
652	
653	  if (ret < 0)
654	    {
655	      syslog(LOG_WARNING, "[ARMINO] queue %u send failed: %d isr=%d\n",
656	             q->id, ret, up_interrupt_context());
657	      return errQUEUE_FULL;
658	    }
659	
660	  armino_queue_hiwater(q);
661	  return pdPASS;
662	}
663	
664	BaseType_t xQueueGenericSend(QueueHandle_t q, const void *const item,
665	                             TickType_t ticks, const BaseType_t pos)
666	{
667	  if (armino_is_semaphore(q))
668	    {
669	      return armino_sem_give(q);
670	    }
671	
672	  if (armino_is_mutex(q))
673	    {
674	      return nxrmutex_unlock(&q->u.mutex) == OK ? pdPASS : pdFAIL;
675	    }
676	
677	  return armino_queue_send(q, item, ticks, pos);
678	}
