680	BaseType_t xQueueGenericSendFromISR(QueueHandle_t q, const void *const item,
681	                                    BaseType_t *const woken,
682	                                    const BaseType_t pos)
683	{
684	  if (woken != NULL)
685	    {
686	      *woken = pdFALSE;
687	    }
688	
689	  if (armino_is_semaphore(q))
690	    {
691	      return armino_sem_give(q);
692	    }
693	
694	  return armino_queue_send(q, item, 0, pos);
695	}
