797	/****************************************************************************
798	 * Software timers on HPWORK
799	 ****************************************************************************/
800	
801	struct armino_timer_s;
802	typedef struct armino_timer_s *TimerHandle_t;
803	typedef void (*TimerCallbackFunction_t)(TimerHandle_t);
804	
805	struct armino_timer_s
806	{
807	  struct work_s work;
808	  TickType_t period;
809	  BaseType_t reload;
810	  void *id;
811	  TimerCallbackFunction_t cb;
812	  volatile bool active;
813	};
814	
815	static void armino_timer_worker(void *arg)
816	{
817	  TimerHandle_t t = arg;
818	
819	  if (!t->active)
820	    {
821	      return;
822	    }
823	
824	  if (t->reload)
825	    {
826	      work_queue(HPWORK, &t->work, armino_timer_worker, t, t->period);
827	    }
828	  else
829	    {
830	      t->active = false;
831	    }
832	
833	  t->cb(t);
834	}
835	
836	TimerHandle_t xTimerCreate(const char *const name, const TickType_t period,
837	                           const BaseType_t reload, void *const id,
838	                           TimerCallbackFunction_t cb)
839	{
840	  TimerHandle_t t = kmm_zalloc(sizeof(*t));
841	
842	  (void)name;
843	  if (t != NULL)
844	    {
845	      t->period = period;
846	      t->reload = reload;
847	      t->id = id;
848	      t->cb = cb;
849	    }
850	
851	  return t;
852	}
853	
854	BaseType_t xTimerGenericCommand(TimerHandle_t t, const BaseType_t cmd,
855	                                const TickType_t value,
856	                                BaseType_t *const woken,
857	                                const TickType_t ticks)
858	{
859	  (void)ticks;
860	
861	  if (woken != NULL)
862	    {
863	      *woken = pdFALSE;
864	    }
865	
866	  switch (cmd)
867	    {
868	      case tmrCOMMAND_CHANGE_PERIOD:
869	      case tmrCOMMAND_CHANGE_PERIOD_FROM_ISR:
870	        t->period = value;
871	
872	        /* FreeRTOS starts a timer whose period is changed. */
873	
874	        /* fallthrough */
875	
876	      case tmrCOMMAND_START:
877	      case tmrCOMMAND_RESET:
878	      case tmrCOMMAND_START_FROM_ISR:
879	      case tmrCOMMAND_START_FROM_ISR + 1:   /* tmrCOMMAND_RESET_FROM_ISR */
880	        work_cancel(HPWORK, &t->work);
881	        t->active = true;
882	        return work_queue(HPWORK, &t->work, armino_timer_worker, t,
883	                          t->period) == OK ? pdPASS : pdFAIL;
884	
885	      case tmrCOMMAND_STOP:
886	      case tmrCOMMAND_STOP_FROM_ISR:
887	        t->active = false;
888	        work_cancel(HPWORK, &t->work);
889	        return pdPASS;
890	
891	      case tmrCOMMAND_DELETE:
892	
893	        /* ponytail: a callback already running on HPWORK may still hold
894	         * t; Armino deletes timers from its own task after stopping them.
