                take = (size_t)chunk_left < avail ? (size_t)chunk_left : avail;

                rc = stream_feed_lines(acc, &acc_len, VELA_TLS_STREAM_LINE_MAX,
                                       r.buf + r.pos, take, cb, user);
                r.pos += take;
                chunk_left -= (long)take;
                if (rc != 0) {
                    err = rc;
                    break;
                }
                if (chunk_left == 0) {
                    state = ST_CRLF;
                }
            } else {
                char c;

                if (sr_byte(&r, &c) != 0) {
                    break;
                }
                if (c == '\n') {
                    state = ST_SIZE;
                    szlen = 0;
                }
