1051	/* ── TTS sentence segmentation ─────────────────────────────── */
1052	
1053	/* Long replies sent as one TTS request sound monotonous (no inter-sentence
1054	 * pause) and, past ~4s of audio, hit the streaming response buffer cap and
1055	 * truncate the tail.  Splitting into sentence-sized segments fixes both: each
1056	 * segment is a short, natural utterance and its own synth request, all written
1057	 * to the one open playback handle in order.
1058	 *
1059	 * Segment ceiling: 180 UTF-8 bytes ≈ 60 CJK chars ≈ 12s of speech at the
1060	 * ~4 chars/s rate, comfortably under the 512KB stream cap. */
1061	#define TTS_SEGMENT_MAX 180
1062	
1063	/* UTF-8 byte length of a sentence terminator at p (0 = not a terminator):
1064	 * ASCII \n ! ?, or full-width 。！？； (3 bytes each). */
1065	static int tts_terminator_len(const char *p)
1066	{
1067	  unsigned char c = (unsigned char)p[0];
1068	
1069	  if (c == '\n' || c == '!' || c == '?') {
1070	    return 1;
1071	  }
1072	  /* 。 U+3002 (E3 80 82) */
1073	  if (c == 0xE3 && (unsigned char)p[1] == 0x80
1074	      && (unsigned char)p[2] == 0x82) {
1075	    return 3;
1076	  }
1077	  /* ！ U+FF01 / ？ U+FF1F / ； U+FF1B (EF BC 81 / 9F / 9B) */
1078	  if (c == 0xEF && (unsigned char)p[1] == 0xBC
1079	      && ((unsigned char)p[2] == 0x81 || (unsigned char)p[2] == 0x9F
1080	          || (unsigned char)p[2] == 0x9B)) {
1081	    return 3;
1082	  }
1083	  return 0;
1084	}
1085	
1086	/* Return the start of the segment that follows `s`: just past the first
1087	 * sentence terminator (trailing whitespace skipped), or — when none appears
1088	 * within TTS_SEGMENT_MAX bytes — a forced split rounded down to a UTF-8
1089	 * character boundary so a multi-byte char is never cut in half. */
1090	static char *tts_next_segment(char *s)
1091	{
1092	  char *p = s;
1093	  size_t run = 0;
1094	
1095	  while (*p) {
1096	    int tlen = tts_terminator_len(p);
1097	
1098	    if (tlen) {
1099	      p += tlen;  /* keep the terminator with the current sentence */
1100	      while (*p == '\n' || *p == ' ' || *p == '\t') {
1101	        p++;
1102	      }
1103	      return p;
1104	    }
1105	
1106	    p++;
1107	    run++;
1108	    if (run >= TTS_SEGMENT_MAX) {
1109	      /* Continuation bytes are 0x80..0xBF; back up to the leading byte. */
1110	      while (p > s && ((unsigned char)p[0] & 0xC0) == 0x80) {
1111	        p--;
1112	      }
1113	      return p;
1114	    }
1115	  }
1116	  return p;  /* end of string */
1117	}
