            + (w1.tv_nsec - w0.tv_nsec) / 1000000;

        s_tts_chunks++;

        syslog(LOG_INFO,
            "[%s] tts chunk %d: +%ldms (gap %ldms) len=%zu write=%ldms\n",
            TAG, s_tts_chunks, recv_ms,
