/* Read the HTTP response header block into raw[0..*len).  Returns 0 on
 * success, or VELA_TLS_ERR_* on failure. */
static int stream_read_headers(stream_reader_t* r, char* raw, size_t* len)
{
    int ret;

    for (;;) {
        ret = mbedtls_ssl_read(&r->ctx->ssl, (unsigned char*)(raw + *len),
                               TLS_RAW_BUF_SIZE - 1 - *len);
        if (ret > 0) {
            *len += (size_t)ret;
            if (memmem(raw, *len, "\r\n\r\n", 4)) {
