    ret = cif_msg_sender(buf,CIF_TASK_MSG_EVT,0);
    
    if (ret != BK_OK)
    {
        CIF_LOGE("%s,%d,error type:%d\n",__func__,__LINE__,ret);
        cif_free_cmd_buffer((uint8_t*)buf);
        return BK_FAIL;
    }


    return BK_OK;
}
