{
    uint8_t num_temp = 0;
    uint8_t ret = BK_OK;
    void * temp_next = NULL;
    cif_chnl_node_t *node = (cif_chnl_node_t*)payload;
    uint8_t chan_id = node->channel;
    void * head = node->head;
    void * tail = node->tail;
    uint8_t num = node->num;

    CIF_LOGV("%s,chan_id=%d,head=0x%x,tail=0x%x,num=%d,start!\n",__func__,chan_id,head,tail,num);

    while(head != NULL)
