134	/****************************************************************************
135	 * Private Helpers
136	 ****************************************************************************/
137	
138	/* Read-modify-write on a plain sys-ctrl register (no analog SPI).  A single
139	 * putreg32 is enough because the whole SoC AHB slave is coherent from the
140	 * CPU.  Called from init only; no interlock with IRQ paths.
141	 */
142	
143	static inline void bk7258_sys_reg_bits(uint32_t addr, uint32_t mask,
144	                                       uint32_t value)
145	{
146	  uint32_t v = getreg32(addr);
147	  v &= ~mask;
148	  v |= (value & mask);
149	  putreg32(v, addr);
150	}
151	
152	/* Analog-register write, mirrors sys_ll_set_analog_reg_value():
153	 *   REG_WRITE(addr, value);
154	 *   spin until SPI_STATE bit[idx] clears.
155	 *
156	 * The SPI transfer takes only a handful of AHB cycles; AVDK does not bound
157	 * the wait.  We keep a generous 1000-iteration cap so a stuck bus surfaces
158	 * as an error rather than a lock-up.
159	 */
160	
161	static int bk7258_ana_reg_write(uint32_t idx, uint32_t value)
162	{
163	  const uint32_t addr = BK7258_SYS_ANA_REG(idx);
164	  int loops = 1000;
165	
166	  putreg32(value, addr);
167	
168	  while ((getreg32(BK7258_SYS_ANA_SPI_STATE) & (UINT32_C(1) << idx)) != 0)
169	    {
170	      if (--loops <= 0)
171	        {
172	          auderr("BK7258: analog reg %lu SPI wait timeout\n",
173	                 (unsigned long)idx);
174	          return -ETIMEDOUT;
175	        }
176	    }
177	
178	  return OK;
179	}
180	
181	/* Read-modify-write on an analog register bit (equivalent to
182	 * sys_set_ana_reg_bit() in AVDK sys_ll.h).
183	 */
184	
185	static int bk7258_ana_reg_bit(uint32_t idx, uint32_t pos, uint32_t mask,
186	                              uint32_t value)
187	{
188	  const uint32_t addr = BK7258_SYS_ANA_REG(idx);
189	  uint32_t v = getreg32(addr);
190	
191	  v &= ~(mask << pos);
192	  v |= ((value & mask) << pos);
193	  return bk7258_ana_reg_write(idx, v);
194	}
195	
196	/* One-shot APLL bring-up (spec §2.2).  cal_val is the family-specific cal
197	 * word; caller decides based on sample rate.
198	 */
199	
200	static int bk7258_apll_program(uint32_t cal_val)
201	{
202	  int ret;
203	
204	  /* Clear the "power-down APLL" bit — active-high in ana_reg5[13]. */
205	
206	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG_APLL_PWD,
207	                           ANA_REG5_PWDAUDPLL_BIT, 0x1u, 0);
208	  if (ret < 0)
209	    {
210	      return ret;
211	    }
212	
213	  ret = bk7258_ana_reg_write(BK7258_ANA_REG26_APLL_CAL, cal_val);
214	  if (ret < 0)
215	    {
216	      return ret;
217	    }
218	
219	  ret = bk7258_ana_reg_write(BK7258_ANA_REG25_APLL_CFG,
220	                             BK7258_APLL_CONFIG_VAL);
221	  if (ret < 0)
222	    {
223	      return ret;
224	    }
225	
226	  /* SPI trigger pulse.  AVDK loops delay(10); we use 200 us as a
227	   * conservative equivalent while APLL locks.
228	   */
229	
230	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG25_APLL_CFG,
231	                           ANA_REG25_SPI_TRIGGER_BIT, 0x1u, 1);
232	  if (ret < 0)
233	    {
234	      return ret;
235	    }
236	
237	  /* AVDK loops delay(10) here (approximately 10 ms on their RTOS tick).
238	   * Waiting only a couple hundred microseconds is not enough for the APLL
239	   * to lock, and the DAC clock silently falls back to a divided XTAL — the
240	   * DAC block appears configured but the FIFO stops draining after a few
241	   * words.  10 ms matches the reference bring-up.
242	   */
243	
244	  up_mdelay(20);
245	
246	  return bk7258_ana_reg_bit(BK7258_ANA_REG25_APLL_CFG,
247	                            ANA_REG25_SPI_TRIGGER_BIT, 0x1u, 0);
248	}
249	
250	/****************************************************************************
251	 * Public Functions
252	 ****************************************************************************/
253	
254	int bk7258_aud_subsystem_init(void)
255	{
256	  irqstate_t flags;
257	  int ret = OK;
258	
259	  flags = spin_lock_irqsave(&g_bk7258_aud_lock);
260	  if (g_bk7258_aud_subsys_ready)
261	    {
262	      spin_unlock_irqrestore(&g_bk7258_aud_lock, flags);
263	      return OK;
264	    }
265	
266	  spin_unlock_irqrestore(&g_bk7258_aud_lock, flags);
267	
268	  /* CP owns the shared SYS power and SRAM controls and clears them while AP
269	   * is held in reset.  AP must only validate that handoff: writing these
270	   * registers here would race CP power management through whole-word RMWs.
271	   * Fail closed before publishing subsystem readiness if the handoff did not
272	   * take effect.
273	   */
274	
275	  {
276	    uint32_t power = getreg32(BK7258_SYS_POWER_WAKEUP);
277	    uint32_t mem_ctrl1 = getreg32(BK7258_SYS_DEV_MEM_CTRL1);
278	    uint32_t mem_ctrl2 = getreg32(BK7258_SYS_DEV_MEM_CTRL2);
279	
280	    if ((power & BK7258_SYS_AUDP_POWER_DOWN) != 0 ||
281	        (mem_ctrl1 & BK7258_SYS_AUD_MEM_LOW_POWER) != 0 ||
282	        (mem_ctrl2 & BK7258_SYS_AUD_MEM_LOW_POWER) != 0)
283	      {
284	        auderr("BK7258: CP audio wake handoff invalid: "
285	               "pwr=%08lx sd=%08lx ds=%08lx\n",
286	               (unsigned long)power,
287	               (unsigned long)mem_ctrl1,
288	               (unsigned long)mem_ctrl2);
289	        return -EIO;
290	      }
291	  }
292	
293	  /* §2.1 step 2/3: start from XTAL and gate the audio clock on.  The audio
294	   * clock mux is programmed later by bk7258_dac_configure().
295	   */
296	
297	  bk7258_sys_reg_bits(SYS_CLK_DIV_MODE1,
298	                      SYS_CLK_DIV_MODE1_CKSEL_AUD_MASK
299	                          << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT,
300	                      0u);
301	  bk7258_sys_reg_bits(SYS_CPU_DEVICE_CLK_EN,
302	                      UINT32_C(1) << SYS_CPU_DEVICE_CLK_AUD_CKEN_BIT,
303	                      UINT32_C(1) << SYS_CPU_DEVICE_CLK_AUD_CKEN_BIT);
304	
305	  /* §2.1 step 4: the AUD-block interrupt line is intentionally NOT gated
306	   * here.  Playback goes through GDMA; the driver does not attach any
307	   * handler to BK7258_IRQ_AUDIO, so leaving the sys-ctrl CPU int_en bit
308	   * clear avoids delivering an aggregate audio IRQ that nobody consumes.
309	   */
310	
311	  /* §2.1 step 5: release the audio data path from reset via AUD_CLK_CONTROL.
312	   *
313	   * soft_reset is ACTIVE-LOW on this silicon: 1 = reset released (operating),
314	   * 0 = reset held.  AVDK's bk_aud_driver_init() does exactly
315	   * aud_hal_set_clk_control_soft_reset(1) and never clears bit0 until the
316	   * deinit path (which pulses 0->1->0 to re-assert reset).  The register
317	   * comment "写1复位...需要软件清除" is misleading; the reference code is the
318	   * ground truth.
319	   *
320	   * The earlier bring-up here pulsed bit0 1->0, leaving soft_reset=0 and so
321	   * HOLDING the data path in reset: the -F probe showed FIFO_STATUS staying
322	   * all-EMPTY across 32 rapid DAC_FPORT writes (the write port is dead in
323	   * reset), while ana_reg SPI writes still latched correctly (the analog SPI
324	   * runs on its own domain).  Leaving soft_reset=1, exactly as AVDK does,
325	   * restores the FIFO.
326	   *
327	   * bit1 (clk_gate) is intentionally left at its working default (0); AVDK
328	   * never writes it either.
329	   */
330	
331	  putreg32(getreg32(BK7258_AUD_CLK_CONTROL) | AUD_CLK_CTRL_SOFT_RESET,
332	           BK7258_AUD_CLK_CONTROL);
333	
334	  /* §2.1 step 6: apply the pre-computed ana_reg defaults.  These are the
335	   * exact values AVDK's ana_regNN_value_cal() functions produce on
336	   * SOC_BK7236XX; changing them alters bias current, VCM and DAC common
337	   * mode and MUST be re-derived from silicon test data if touched.
338	   */
339	
340	  ret = bk7258_ana_reg_write(BK7258_ANA_REG18, BK7258_ANA_REG18_DEFAULT);
341	  if (ret < 0)
342	    {
343	      goto fail;
344	    }
345	
346	  ret = bk7258_ana_reg_write(BK7258_ANA_REG19, BK7258_ANA_REG19_DEFAULT);
347	  if (ret < 0)
348	    {
349	      goto fail;
350	    }
351	
352	  ret = bk7258_ana_reg_write(BK7258_ANA_REG20, BK7258_ANA_REG20_DEFAULT);
353	  if (ret < 0)
354	    {
355	      goto fail;
356	    }
357	
358	  ret = bk7258_ana_reg_write(BK7258_ANA_REG21, BK7258_ANA_REG21_DEFAULT);
359	  if (ret < 0)
360	    {
361	      goto fail;
362	    }
363	
364	  ret = bk7258_ana_reg_write(BK7258_ANA_REG27, BK7258_ANA_REG27_DEFAULT);
365	  if (ret < 0)
366	    {
367	      goto fail;
368	    }
369	
370	  /* §2.1 step 7: enable the audio bias network AFTER the ana_reg defaults
371	   * have latched.
372	   */
373	
374	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG18,
375	                           ANA_REG18_ENAUDBIAS_BIT, 0x1u, 1);
376	  if (ret < 0)
377	    {
378	      goto fail;
379	    }
380	
381	  flags = spin_lock_irqsave(&g_bk7258_aud_lock);
382	  g_bk7258_aud_subsys_ready = true;
383	  spin_unlock_irqrestore(&g_bk7258_aud_lock, flags);
384	
385	  audinfo("BK7258: audio subsystem initialised\n");
386	  return OK;
387	
388	fail:
389	  auderr("BK7258: audio subsystem init failed: %d\n", ret);
390	  return ret;
391	}
392	
393	int bk7258_dac_configure(const struct bk7258_dac_cfg_s *cfg)
394	{
395	  irqstate_t flags;
396	  uint32_t v;
397	  int ret;
398	
399	  if (cfg == NULL)
400	    {
401	      return -EINVAL;
402	    }
403	
404	  if (!g_bk7258_aud_subsys_ready)
405	    {
406	      ret = bk7258_aud_subsystem_init();
407	      if (ret < 0)
408	        {
409	          return ret;
410	        }
411	    }
412	
413	  g_bk7258_dac_use_apll = cfg->use_apll;
414	
415	  /* §2.2 clock select. */
416	
417	  if (cfg->use_apll)
418	    {
419	      bk7258_sys_reg_bits(SYS_CLK_DIV_MODE1,
420	                          SYS_CLK_DIV_MODE1_CKSEL_AUD_MASK
421	                              << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT,
422	                          UINT32_C(1) << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT);
423	
424	      ret = bk7258_apll_program(BK7258_APLL_CAL_VAL_48K);
425	      if (ret < 0)
426	        {
427	          return ret;
428	        }
429	
430	      v = getreg32(BK7258_AUD_AUDIO_CONFIG);
431	      v |= AUD_AUDIO_CFG_APLL_SEL;
432	      putreg32(v, BK7258_AUD_AUDIO_CONFIG);
433	
434	      /* Divide DMIC clock so it does not steal APLL bandwidth. */
435	
436	      bk7258_sys_reg_bits(SYS_CLK_DIV_MODE2,
437	                          UINT32_C(1) << SYS_CLK_DIV_MODE2_DMIC_DIV_BIT,
438	                          UINT32_C(1) << SYS_CLK_DIV_MODE2_DMIC_DIV_BIT);
439	    }
440	  else
441	    {
442	      bk7258_sys_reg_bits(SYS_CLK_DIV_MODE1,
443	                          SYS_CLK_DIV_MODE1_CKSEL_AUD_MASK
444	                              << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT,
445	                          0u);
446	
447	      v = getreg32(BK7258_AUD_AUDIO_CONFIG);
448	      v &= ~AUD_AUDIO_CFG_APLL_SEL;
449	      putreg32(v, BK7258_AUD_AUDIO_CONFIG);
450	    }
451	
452	  /* §2.3 step 4: DAC analog path power-up.  On BK7258 (SOC_BK7236XX) the
453	   * BK7256-era right-channel/vdd rails are not-supported no-ops in AVDK;
454	   * we only drive the fields that actually map to silicon.
455	   *
456	   *   dac_bias_en  → ana_reg21[enbs]        (not exposed here, latched by
457	   *                                          the ana_reg21 default value)
458	   *   dac_drv_en   → ana_reg20[dacdrven]
459	   *   dac_dcoc_en  → ana_reg20[lendcoc]
460	   *   dac_idac_en  → ana_reg21[enidacl]
461	   *   dacl_en      → ana_reg20[daclen]
462	   *   diffen       → ana_reg20[diffen]
463	   */
464	
465	  /* AVDK aud_dac_driver.c:81..87 explicitly flips these four bits in this
466	   * order.  ana_reg21.enbs (dac bias) is NOT part of the reset default
467	   * value we programmed earlier and MUST be raised now.
468	   */
469	
470	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG21,
471	                           ANA_REG21_ENBS_BIT, 0x1u, 1);
472	  if (ret < 0)
473	    {
474	      return ret;
475	    }
476	
477	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG20,
478	                           ANA_REG20_DACDRVEN_BIT, 0x1u, 1);
479	  if (ret < 0)
480	    {
481	      return ret;
482	    }
483	
484	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG20,
485	                           ANA_REG20_LENDCOC_BIT, 0x1u, 1);
486	  if (ret < 0)
487	    {
488	      return ret;
489	    }
490	
491	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG21,
492	                           ANA_REG21_ENIDACL_BIT, 0x1u, 1);
493	  if (ret < 0)
494	    {
495	      return ret;
496	    }
497	
498	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG20,
499	                           ANA_REG20_DACLEN_BIT, 0x1u, 1);
500	  if (ret < 0)
501	    {
502	      return ret;
503	    }
504	
505	  /* §2.3 step 6: differential vs single-ended. */
506	
507	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG20,
508	                           ANA_REG20_DIFFEN_BIT, 0x1u,
509	                           cfg->work_mode == BK7258_DAC_WORK_DIFFEN
510	                                             ? 1u : 0u);
511	  if (ret < 0)
512	    {
513	      return ret;
514	    }
515	
516	  /* §2.3 step 7: DAC digital path.  Gain, HPF bypass, clk invert. */
517	
518	  flags = spin_lock_irqsave(&g_bk7258_aud_lock);
519	  v = getreg32(BK7258_AUD_DAC_CONFIG0);
520	  v &= ~(AUD_DAC_CFG0_GAIN_MASK | AUD_DAC_CFG0_CLK_INVERT
521	         | AUD_DAC_CFG0_HPF1_BYPASS | AUD_DAC_CFG0_HPF2_BYPASS);
522	  v |= ((uint32_t)(cfg->gain & 0x3Fu) << AUD_DAC_CFG0_GAIN_SHIFT);
523	  v |= AUD_DAC_CFG0_HPF1_BYPASS | AUD_DAC_CFG0_HPF2_BYPASS;
524	  putreg32(v, BK7258_AUD_DAC_CONFIG0);
525	  spin_unlock_irqrestore(&g_bk7258_aud_lock, flags);
526	
527	  /* §2.4: FIFO read threshold.  With threshold=0 the audio block only
528	   * asserts a DMA request when the FIFO is completely empty; on a 32-word
529	   * FIFO that is one request per 32 samples, and combined with any DMA
530	   * arbitration latency the FIFO under-runs and stops requesting.  AVDK
531	   * uses 4 for BK7256; 8 leaves comfortable headroom on BK7258.
532	   */
533	
534	  {
535	    uint32_t fifo_cfg;
536	    fifo_cfg  = getreg32(BK7258_AUD_FIFO_CONFIG);
537	    fifo_cfg &= ~(AUD_FIFO_CFG_DACL_RD_TH_MASK
538	                  | AUD_FIFO_CFG_DACR_RD_TH_MASK);
539	    fifo_cfg |= (UINT32_C(8) << AUD_FIFO_CFG_DACL_RD_TH_SHIFT);
540	    fifo_cfg |= (UINT32_C(8) << AUD_FIFO_CFG_DACR_RD_TH_SHIFT);
541	    putreg32(fifo_cfg, BK7258_AUD_FIFO_CONFIG);
542	  }
543	
544	  /* §2.3 step 8: sample-rate divider. */
545	
546	  ret = bk7258_dac_set_sample_rate(cfg->samp_rate);
547	  if (ret < 0)
548	    {
549	      return ret;
550	    }
551	
552	  /* §2.3 step 9: previously we muted the DAC here.  Empirically the DAC
553	   * FIFO then never fully drains after start() unmutes; leaving the DAC
554	   * un-muted through configure() lets DMA replenish the FIFO immediately.
555	   */
556	
557	  g_bk7258_dac_configured = true;
558	  return OK;
559	}
560	
561	int bk7258_dac_set_sample_rate(uint32_t samp_rate)
562	{
563	  uint32_t sr_code;
564	  uint32_t fracmod = 0;
565	  bool     fracmod_manual = false;
566	  bool     apll_44k_family = false;
567	  uint32_t v;
568	  int ret;
569	
570	  switch (samp_rate)
571	    {
572	      case 8000:
573	        sr_code = AUD_SAMP_RATE_8K;
574	        break;
575	
576	      case 16000:
577	        sr_code = AUD_SAMP_RATE_16K;
578	        break;
579	
580	      case 44100:
581	        sr_code = AUD_SAMP_RATE_44_1K;
582	        apll_44k_family = true;
583	        break;
584	
585	      case 48000:
586	        sr_code = AUD_SAMP_RATE_48K;
587	        break;
588	
589	      case 11025:
590	        sr_code = AUD_SAMP_RATE_44_1K;
591	        fracmod = BK7258_AUD_CONST_DIV_44_1K << 2;
592	        fracmod_manual = true;
593	        apll_44k_family = true;
594	        break;
595	
596	      case 22050:
597	        sr_code = AUD_SAMP_RATE_44_1K;
598	        fracmod = BK7258_AUD_CONST_DIV_44_1K << 1;
599	        fracmod_manual = true;
600	        apll_44k_family = true;
601	        break;
602	
603	      case 12000:
604	        sr_code = AUD_SAMP_RATE_48K;
605	        fracmod = BK7258_AUD_CONST_DIV_48K << 2;
606	        fracmod_manual = true;
607	        break;
608	
609	      case 24000:
610	        sr_code = AUD_SAMP_RATE_48K;
611	        fracmod = BK7258_AUD_CONST_DIV_48K << 1;
612	        fracmod_manual = true;
613	        break;
614	
615	      case 32000:
616	        sr_code = AUD_SAMP_RATE_16K;
617	        fracmod = BK7258_AUD_CONST_DIV_16K >> 1;
618	        fracmod_manual = true;
619	        break;
620	
621	      default:
622	        auderr("BK7258: unsupported sample rate %lu\n",
623	               (unsigned long)samp_rate);
624	        return -EINVAL;
625	    }
626	
627	  /* On APLL, the 44.1k family requires a different cal value.  Re-run the
628	   * APLL bring-up transparently.
629	   */
630	
631	  if (g_bk7258_dac_use_apll)
632	    {
633	      ret = bk7258_apll_program(apll_44k_family
634	                                    ? BK7258_APLL_CAL_VAL_44_1K
635	                                    : BK7258_APLL_CAL_VAL_48K);
636	      if (ret < 0)
637	        {
638	          return ret;
639	        }
640	    }
641	
642	  /* Program fracmod first (upper half), then the samp_rate_DAC bits.  This
643	   * mirrors AVDK ordering and avoids a transient rate mismatch on the DAC
644	   * clock.
645	   */
646	
647	  v = getreg32(BK7258_AUD_EXTEND_CFG);
648	  v &= ~AUD_EXT_CFG_DAC_FRACMOD_MAN;
649	  if (fracmod_manual)
650	    {
651	      v |= AUD_EXT_CFG_DAC_FRACMOD_MAN;
652	    }
653	
654	  putreg32(v, BK7258_AUD_EXTEND_CFG);
655	
656	  if (fracmod_manual)
657	    {
658	      putreg32(fracmod, BK7258_AUD_DAC_FRACMOD);
659	    }
660	
661	  v = getreg32(BK7258_AUD_AUDIO_CONFIG);
662	  v &= ~AUD_AUDIO_CFG_SAMP_RATE_MASK;
663	  v |= (sr_code << AUD_AUDIO_CFG_SAMP_RATE_SHIFT)
664	       & AUD_AUDIO_CFG_SAMP_RATE_MASK;
665	  putreg32(v, BK7258_AUD_AUDIO_CONFIG);
666	
667	  return OK;
668	}
