38	/* Pre-computed ana_reg default values.  AVDK ships equivalent field-by-field
39	 * builders (aud_common_driver.c:153..291).  The hex constants below are the
40	 * comments AVDK itself left in place for reference, and match the runtime
41	 * value_cal() output field-for-field on BK7258 (SOC_BK7236XX branch).
42	 */
43	
44	#define BK7258_ANA_REG18_DEFAULT      UINT32_C(0x00BF8085)
45	#define BK7258_ANA_REG19_DEFAULT      UINT32_C(0x81800006)
46	#define BK7258_ANA_REG20_DEFAULT      UINT32_C(0xFBC02423)
47	#define BK7258_ANA_REG21_DEFAULT      UINT32_C(0x00500000)
48	#define BK7258_ANA_REG27_DEFAULT      UINT32_C(0x91800006)
49	
50	/* Analog-reg indices used by the DAC path.
51	 *
52	 * These are the AVDK "ana_reg N" logical register numbers, which are also
53	 * the word OFFSET from ana_reg0 (SYS_ANA_REG0_ADDR = SOC_SYS_REG_BASE +
54	 * (0x40<<2)).  AVDK addresses e.g. ana_reg5 at SOC_SYS_REG_BASE + (0x45<<2)
55	 * = reg0 + (5<<2); so BK7258_SYS_ANA_REG(n) = (reg0 base) + n*4 with
56	 * BK7258_SYS_ANALOG_REG_BASE already pointing at reg0 (word 0x40) gives the
57	 * correct physical address when n is the logical number (5, not 0x45).
58	 *
59	 * The same n is the SYS_ANALOG_REG_SPI_STATE busy bit number
60	 * (vendor: SYS_ANALOG_REG_SPI_STATE_POS(idx) = idx where idx is the
61	 * reg0-relative word offset), so bk7258_ana_reg_write()'s "1 << idx"
62	 * busy-wait matches vendor.  Passing the absolute word index (0x45 etc.)
63	 * here is WRONG — it double-counts the reg0 offset and writes 0x100 bytes
64	 * past the real register (verified: all ana_reg read back 0 in -F).
65	 */
66	#define BK7258_ANA_REG_APLL_PWD       5    /* AVDK "ana_reg5", pwdaudpll bit 13. */
67	#define BK7258_ANA_REG18              18
68	#define BK7258_ANA_REG19              19
69	#define BK7258_ANA_REG20              20
70	#define BK7258_ANA_REG21              21
71	#define BK7258_ANA_REG25_APLL_CFG     25
72	#define BK7258_ANA_REG26_APLL_CAL     26
73	#define BK7258_ANA_REG27              27
74	
75	/* ana_reg20 bit positions we RMW at runtime.  All widths are 1 bit unless
76	 * annotated.  Values traced from sys_ll.h.
77	 */
78	
79	#define ANA_REG20_DACDRVEN_BIT        19
80	#define ANA_REG20_DACLEN_BIT          21
81	#define ANA_REG20_DACG_BIT            22    /* 4-bit field.                */
82	#define ANA_REG20_DACG_MASK           0xFu
83	#define ANA_REG20_DACMUTE_BIT         26
84	#define ANA_REG20_DIFFEN_BIT          13
85	#define ANA_REG20_LENDCOC_BIT         16
86	
87	/* ana_reg21 bit positions. */
88	
89	#define ANA_REG21_ENIDACL_BIT         18
90	#define ANA_REG21_ENBS_BIT            23  /* sys_reg.h: SYS_ANA_REG21_ENBS_POS */
91	
92	/* ana_reg18 bit positions. */
93	
94	#define ANA_REG18_ENAUDBIAS_BIT       3
95	
96	/* ana_reg5[13] = pwdaudpll (active-high power-DOWN). */
97	
98	#define ANA_REG5_PWDAUDPLL_BIT        13
99	
100	/* ana_reg25[18] = APLL SPI trigger. */
101	
102	#define ANA_REG25_SPI_TRIGGER_BIT     18
103	
104	/* Sys ctrl (0x44010000) register offsets used at runtime. */
105	
106	/* Sys ctrl register bit positions taken from the AVDK sys_struct.h layout
107	 * for BK7258 (bk_avdk_smp/ap/middleware/soc/bk7258_ap/soc/sys_struct.h).
108	 */
109	
110	#define SYS_CLK_DIV_MODE1             (BK7258_SYS_BASE + (0x8u * 4u))
111	#define   SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT   25  /* sys_struct.h:144 */
112	#define   SYS_CLK_DIV_MODE1_CKSEL_AUD_MASK  0x1u
113	
114	#define SYS_CLK_DIV_MODE2             (BK7258_SYS_BASE + (0x9u * 4u))
115	#define   SYS_CLK_DIV_MODE2_DMIC_DIV_BIT    13  /* sys_struct.h:163 */
116	
117	#define SYS_CPU_DEVICE_CLK_EN         (BK7258_SYS_BASE + (0xCu * 4u))
118	#define   SYS_CPU_DEVICE_CLK_AUD_CKEN_BIT   30  /* sys_struct.h:238 */
