670	void bk7258_dac_set_gain(uint8_t gain)
671	{
672	  irqstate_t flags;
673	  uint32_t v;
674	
675	  if (gain > 0x3Fu)
676	    {
677	      gain = 0x3Fu;
678	    }
679	
680	  flags = spin_lock_irqsave(&g_bk7258_aud_lock);
681	  v = getreg32(BK7258_AUD_DAC_CONFIG0);
682	  v &= ~AUD_DAC_CFG0_GAIN_MASK;
683	  v |= ((uint32_t)gain << AUD_DAC_CFG0_GAIN_SHIFT);
684	  putreg32(v, BK7258_AUD_DAC_CONFIG0);
685	  spin_unlock_irqrestore(&g_bk7258_aud_lock, flags);
686	}
