151	/* Map upper-half 0..100 volume to a DAC digital-gain register value.
152	 * The endpoints match spec §3: v=0 mutes; v=100 -> AVDK 0 dB default;
153	 * intermediates use a linear ramp for now, replaced by a dB LUT once
154	 * silicon measurement data is available.
155	 */
156	
157	static uint8_t bk7258_volume_to_gain(uint8_t volume)
158	{
159	  if (volume == 0)
160	    {
161	      return 0;
162	    }
163	
164	  if (volume >= 100)
165	    {
166	      return BK7258_AUDIO_MAX_DAC_GAIN;
167	    }
168	
169	  return (uint8_t)(((uint32_t)volume * BK7258_AUDIO_MAX_DAC_GAIN) / 100u);
170	}
