550	
551	static int bk7258_getcaps(FAR struct audio_lowerhalf_s *dev, int type,
552	                          FAR struct audio_caps_s *caps)
553	{
554	  (void)dev;
555	  (void)type;
556	
557	  DEBUGASSERT(caps->ac_len >= sizeof(struct audio_caps_s));
558	
559	  caps->ac_format.hw   = 0;
560	  caps->ac_controls.w  = 0;
561	
562	  switch (caps->ac_type)
563	    {
564	      case AUDIO_TYPE_QUERY:
565	        caps->ac_channels = AUDIO_CHANNELS_RANGE(1, 2);
566	        switch (caps->ac_subtype)
567	          {
568	            case AUDIO_TYPE_QUERY:
569	              caps->ac_controls.b[0] = AUDIO_TYPE_OUTPUT | AUDIO_TYPE_FEATURE;
570	              caps->ac_format.hw     = 1 << (AUDIO_FMT_PCM - 1);
571	              break;
572	
573	            case AUDIO_FMT_PCM:
574	              caps->ac_controls.b[0] = AUDIO_SUBFMT_PCM_S16_LE;
575	              break;
576	
577	            default:
578	              caps->ac_controls.b[0] = AUDIO_SUBFMT_END;
579	              break;
580	          }
581	        break;
582	
583	      case AUDIO_TYPE_OUTPUT:
584	        caps->ac_channels = AUDIO_CHANNELS_RANGE(1, 2);
585	        if (caps->ac_subtype == AUDIO_TYPE_QUERY)
586	          {
587	            caps->ac_controls.hw[0] = AUDIO_SAMP_RATE_8K
588	                                    | AUDIO_SAMP_RATE_16K
589	                                    | AUDIO_SAMP_RATE_44K
590	                                    | AUDIO_SAMP_RATE_48K;
591	          }
592	        break;
593	
594	      case AUDIO_TYPE_FEATURE:
595	        if (caps->ac_subtype == AUDIO_TYPE_QUERY)
596	          {
597	            caps->ac_controls.hw[0] = AUDIO_FU_VOLUME | AUDIO_FU_MUTE;
598	          }
599	        break;
600	
601	      default:
602	        caps->ac_subtype  = 0;
603	        caps->ac_channels = 0;
604	        break;
605	    }
606	
607	  return caps->ac_len;
608	}
