897	#ifdef CONFIG_AUDIO_MULTI_SESSION
898	static int bk7258_start(FAR struct audio_lowerhalf_s *dev,
899	                        FAR void *session)
900	#else
901	static int bk7258_start(FAR struct audio_lowerhalf_s *dev)
902	#endif
903	{
904	  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;
905	  struct bk7258_dac_cfg_s dac_cfg;
906	  irqstate_t flags;
907	  bool notify_fault = false;
908	  int pa_ret;
909	  int ret;
910	
911	#ifdef CONFIG_AUDIO_MULTI_SESSION
912	  (void)session;
913	#endif
914	
915	  flags = spin_lock_irqsave(&priv->lock);
916	  if (priv->closing)
917	    {
918	      spin_unlock_irqrestore(&priv->lock, flags);
919	      return -ESHUTDOWN;
920	    }
921	
922	  if (priv->stopping || priv->fault_pending)
923	    {
924	      spin_unlock_irqrestore(&priv->lock, flags);
925	      return -EBUSY;
926	    }
927	
928	  if (priv->faulted)
929	    {
930	      ret = priv->dma_error < 0 ? priv->dma_error : -EIO;
931	      spin_unlock_irqrestore(&priv->lock, flags);
932	      return ret;
933	    }
934	
935	  if (priv->dac_running)
936	    {
937	      spin_unlock_irqrestore(&priv->lock, flags);
938	      return OK;
939	    }
940	
941	  spin_unlock_irqrestore(&priv->lock, flags);
942	
943	  /* Program the DAC block.  Start muted; unmute happens only after PA
944	   * enable and both of its board-owned settling delays succeed.
945	   */
946	
947	  dac_cfg.samp_rate = priv->sample_rate;
948	  dac_cfg.channel   = BK7258_DAC_CHL_LR;
949	  dac_cfg.work_mode = BK7258_DAC_WORK_DIFFEN;
950	  dac_cfg.gain      = 0;
951	  dac_cfg.use_apll  = true;
952	
953	  ret = bk7258_dac_configure(&dac_cfg);
954	  if (ret < 0)
955	    {
956	      AUD_ERR("dac_configure failed: %d", ret);
957	
958	      /* configure powers the analog path incrementally.  Roll back even
959	       * though configured was never published, so an intermediate failure
960	       * cannot leave DAC rails enabled.
961	       */
962	
963	      (void)bk7258_dac_mute(true);
964	      bk7258_dac_stop();
965	      pa_ret = bk7258_pa_disable();
966	      if (pa_ret < 0)
967	        {
968	          AUD_ERR("PA disable after DAC configure failure: %d", pa_ret);
969	        }
970	
971	      bk7258_dac_deinit();
972	      flags = spin_lock_irqsave(&priv->lock);
973	      priv->configured = false;
974	      priv->dma_active = false;
975	      spin_unlock_irqrestore(&priv->lock, flags);
976	      return ret;
977	    }
978	
979	  /* The chip configure path may leave the digital DAC unmuted.  Assert mute
980	   * immediately, before publishing configured or enabling the PA.
981	   */
982	
983	  ret = bk7258_dac_mute(true);
984	  if (ret < 0)
985	    {
986	      AUD_ERR("dac_mute failed after configure: %d", ret);
987	      goto errout;
988	    }
989	
990	  flags = spin_lock_irqsave(&priv->lock);
991	  priv->configured = true;
992	  spin_unlock_irqrestore(&priv->lock, flags);
993	
994	  if (priv->dma_ch < 0)
995	    {
996	      priv->dma_ch = bk7258_gdma_alloc();
997	      if (priv->dma_ch < 0)
998	        {
999	          ret = priv->dma_ch;
1000	          AUD_ERR("gdma_alloc failed: %d", ret);
1001	          goto errout;
1002	        }
1003	    }
1004	
1005	  /* Settle the PA while the configured DAC is still muted and before the
1006	   * run gate allows any DMA transfer.  This avoids consuming queued audio
1007	   * during the board-owned delays and leaves no asynchronous DMA fault for
1008	   * start() to race with.
1009	   */
1010	
1011	  ret = bk7258_pa_enable();
1012	  if (ret < 0)
1013	    {
1014	      AUD_ERR("PA enable failed: %d", ret);
1015	      goto errout;
1016	    }
1017	
1018	  flags = spin_lock_irqsave(&priv->lock);
1019	  if (priv->closing || priv->stopping || priv->faulted ||
1020	      priv->fault_pending)
1021	    {
1022	      ret = priv->closing ? -ESHUTDOWN :
1023	            (priv->faulted && priv->dma_error < 0 ? priv->dma_error :
1024	             -EBUSY);
1025	      spin_unlock_irqrestore(&priv->lock, flags);
1026	      goto errout;
1027	    }
1028	
1029	  priv->dac_running = true;
1030	  priv->dma_active = false;
1031	  priv->underrun_pending = false;
1032	
1033	  ret = bk7258_start_next_locked(priv);
1034	  if (ret < 0)
1035	    {
1036	      bk7258_fault_locked(priv, ret, true);
1037	      notify_fault = true;
1038	      spin_unlock_irqrestore(&priv->lock, flags);
1039	      goto errout;
1040	    }
1041	
1042	  /* These are non-sleeping register operations.  Keep IRQs disabled until
1043	   * the DAC is started and volume applied so no DMA fault can close the run
1044	   * gate between the final state check and unmute.
1045	   */
1046	
1047	  bk7258_dac_start();
1048	  ret = bk7258_apply_volume(priv);
1049	  if (ret < 0)
1050	    {
1051	      AUD_ERR("apply volume during start failed: %d", ret);
1052	      bk7258_fault_locked(priv, ret, true);
1053	      notify_fault = true;
1054	      spin_unlock_irqrestore(&priv->lock, flags);
1055	      goto errout;
1056	    }
1057	
1058	  spin_unlock_irqrestore(&priv->lock, flags);
1059	  return OK;
1060	
1061	errout:
1062	  /* Complete rollback.  PA disable errors are diagnostic only here: the
1063	   * initiating start error remains the caller-visible result.
1064	   */
1065	
1066	  (void)bk7258_dac_mute(true);
1067	  pa_ret = bk7258_pa_disable();
1068	  if (pa_ret < 0)
1069	    {
1070	      AUD_ERR("PA disable during start rollback failed: %d", pa_ret);
1071	    }
1072	
1073	  bk7258_dac_stop();
1074	  if (priv->dma_ch >= 0)
1075	    {
1076	      bk7258_gdma_stop(priv->dma_ch);
1077	      bk7258_gdma_free(priv->dma_ch);
1078	      priv->dma_ch = -1;
1079	    }
1080	
1081	  bk7258_dac_deinit();
1082	
1083	  flags = spin_lock_irqsave(&priv->lock);
1084	  priv->configured = false;
1085	  priv->dma_active = false;
1086	  if (notify_fault)
1087	    {
1088	      bk7258_schedule_worker_locked(priv);
1089	    }
1090	
1091	  spin_unlock_irqrestore(&priv->lock, flags);
1092	  return ret;
1093	}
