1095	#ifndef CONFIG_AUDIO_EXCLUDE_STOP
1096	#ifdef CONFIG_AUDIO_MULTI_SESSION
1097	static int bk7258_stop(FAR struct audio_lowerhalf_s *dev,
1098	                       FAR void *session)
1099	#else
1100	static int bk7258_stop(FAR struct audio_lowerhalf_s *dev)
1101	#endif
1102	{
1103	  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;
1104	  FAR struct ap_buffer_s *apb;
1105	  irqstate_t flags;
1106	  int pa_ret;
1107	
1108	#ifdef CONFIG_AUDIO_MULTI_SESSION
1109	  (void)session;
1110	#endif
1111	
1112	  /* stopping remains asserted through asynchronous DEQUEUE/COMPLETE so an
1113	   * upper-half refill caused by those callbacks cannot be reacquired.  A
1114	   * later successful OUTPUT configure opens this gate again.
1115	   */
1116	
1117	  flags = spin_lock_irqsave(&priv->lock);
1118	  if (priv->closing)
1119	    {
1120	      spin_unlock_irqrestore(&priv->lock, flags);
1121	      return -ESHUTDOWN;
1122	    }
1123	
1124	  priv->stopping = true;
1125	  priv->dac_running = false;
1126	  priv->dma_active = false;
1127	  priv->complete_pending = false;
1128	  priv->underrun_pending = false;
1129	  priv->final_seen = false;
1130	  spin_unlock_irqrestore(&priv->lock, flags);
1131	
1132	  if (priv->configured)
1133	    {
1134	      (void)bk7258_dac_mute(true);
1135	    }
1136	
1137	  if (priv->dma_ch >= 0)
1138	    {
1139	      bk7258_gdma_stop(priv->dma_ch);
1140	    }
1141	
1142	  bk7258_dac_stop();
1143	  pa_ret = bk7258_pa_disable();
1144	  if (pa_ret < 0)
1145	    {
1146	      AUD_ERR("PA disable during stop failed: %d", pa_ret);
1147	    }
1148	
1149	  flags = spin_lock_irqsave(&priv->lock);
1150	
1151	  /* Return every normally stopped buffer successfully.  Buffers already
1152	   * detached into failq retain their asynchronous error result.
1153	   */
1154	
1155	  while ((apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->pendq)) != NULL)
1156	    {
1157	      dq_addlast(&apb->dq_entry, &priv->doneq);
1158	    }
1159	
1160	  priv->complete_pending = true;
1161	  bk7258_schedule_worker_locked(priv);
1162	  spin_unlock_irqrestore(&priv->lock, flags);
1163	  return OK;
1164	}
1165	#endif
1166	
1167	static int bk7258_enqueuebuffer(FAR struct audio_lowerhalf_s *dev,
1168	                                FAR struct ap_buffer_s *apb)
1169	{
1170	  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;
1171	  irqstate_t flags;
1172	  int ret;
1173	
1174	  DEBUGASSERT(priv && apb);
1175	
1176	  flags = spin_lock_irqsave(&priv->lock);
1177	
1178	  /* Rejection happens before ownership transfer.  In particular, faulted
1179	   * remains latched while error callbacks make upper-half refill attempts.
1180	   */
1181	
1182	  if (priv->closing)
1183	    {
1184	      ret = -ESHUTDOWN;
1185	      goto reject;
1186	    }
1187	
1188	  if (priv->stopping || priv->fault_pending)
1189	    {
1190	      ret = -EBUSY;
1191	      goto reject;
1192	    }
1193	
1194	  if (priv->faulted)
1195	    {
1196	      ret = priv->dma_error < 0 ? priv->dma_error : -EIO;
1197	      goto reject;
1198	    }
1199	
1200	  if ((apb->flags & AUDIO_APB_FINAL) != 0u)
1201	    {
1202	      priv->final_seen = true;
1203	    }
1204	
1205	  dq_addlast(&apb->dq_entry, &priv->pendq);
1206	
1207	  /* Once queued, ownership has transferred.  A synchronous start failure is
1208	   * reported asynchronously by error DEQUEUE; returning an error here as
1209	   * well would make ownership ambiguous to the upper half.
1210	   */
1211	
1212	  if (priv->dac_running && !priv->dma_active)
1213	    {
1214	      ret = bk7258_start_next_locked(priv);
1215	      if (ret < 0)
1216	        {
1217	          bk7258_fault_locked(priv, ret, false);
1218	          bk7258_schedule_worker_locked(priv);
1219	        }
1220	    }
1221	
1222	  spin_unlock_irqrestore(&priv->lock, flags);
1223	  return OK;
1224	
1225	reject:
1226	  spin_unlock_irqrestore(&priv->lock, flags);
1227	  return ret;
1228	}
