1230	static int bk7258_cancelbuffer(FAR struct audio_lowerhalf_s *dev,
1231	                               FAR struct ap_buffer_s *apb)
1232	{
1233	  (void)dev;
1234	  (void)apb;
1235	
1236	  /* Buffers currently owned by DMA cannot be cancelled without a full
1237	   * stop.  Best-effort: report success; the buffer will be dequeued in
1238	   * order.  The upper half is free to call stop() for a hard abort.
1239	   */
1240	
1241	  return OK;
1242	}
