1304	{
1305	  FAR struct bk7258_audio_s *priv;
1306	  int ret;
1307	
1308	  priv = kmm_zalloc(sizeof(struct bk7258_audio_s));
1309	  if (priv == NULL)
1310	    {
1311	      AUD_ERR("alloc failed");
1312	      return -ENOMEM;
1313	    }
1314	
1315	  priv->dev.ops     = &g_bk7258_playback_ops;
1316	  priv->type        = BK7258_AUDIO_TYPE_PLAYBACK;
1317	  priv->sample_rate = BK7258_AUDIO_DEFAULT_SAMPLE_RATE;
1318	  priv->channels    = BK7258_AUDIO_DEFAULT_CHANNELS;
1319	  priv->bpsamp      = BK7258_AUDIO_DEFAULT_BPSAMP;
1320	  priv->volume      = BK7258_AUDIO_DEFAULT_VOLUME;
1321	  priv->mute        = false;
1322	  priv->dma_ch      = -1;
1323	  spin_lock_init(&priv->lock);
1324	  dq_init(&priv->pendq);
1325	  dq_init(&priv->doneq);
1326	  dq_init(&priv->failq);
1327	
1328	  /* Bring the GDMA subsystem up eagerly so the first start() does not have
1329	   * to serialise on it inside the audio-open critical path.
1330	   */
1331	
1332	  ret = bk7258_gdma_initialize();
1333	  if (ret < 0)
1334	    {
1335	      AUD_ERR("gdma_initialize failed: %d", ret);
1336	      kmm_free(priv);
1337	      return ret;
1338	    }
