1352	/****************************************************************************
1353	 * Capture lower-half (/dev/audio/pcm0c)
1354	 *
1355	 * Armino records through GDMA, not FIFO polling: ap/components/audio_record/
1356	 * src/onboard_mic_record.c:440-506 allocates a channel with
1357	 * bk_dma_alloc(DMA_DEV_AUDIO), takes the FIFO port from
1358	 * bk_aud_adc_get_fifo_addr(), and lets DMA_WORK_MODE_REPEAT move samples
1359	 * into a RAM ring with a finish ISR.  The shape here is the same engine
1360	 * with the per-buffer envelope the playback half above already uses.
1361	 ****************************************************************************/
1362	
1363	/* read() mode.  ai_agent's NuttX backend pulls PCM with read() instead of
1364	 * the AUDIOIOC_ENQUEUEBUFFER/DEQUEUE message loop nxrecorder uses.  The
1365	 * first read() switches the device into a driver-owned ring: the same GDMA
1366	 * engine fills rdbuf[] in turn, a filled buffer moves to doneq, and read()
1367	 * copies out of it and hands it back to pendq.  The two modes are
1368	 * exclusive per session; stop() ends either.
1369	 */
1370	
1371	#define CAPTURE_READ_NBUF        3
1372	#define CAPTURE_READ_TIMEOUT_MS  500
1373	
1374	struct bk7258_capture_s
1375	{
1376	  struct audio_lowerhalf_s dev;
1377	  spinlock_t               lock;
1378	  dq_queue_t               pendq;
1379	  dq_queue_t               doneq;    /* read() mode: filled, not yet read */
1380	  sem_t                    readsem;  /* posted per filled buffer and on stop */
1381	  bool                     readmode;
1382	  struct ap_buffer_s       rdbuf[CAPTURE_READ_NBUF];
1383	  volatile bool            running;
1384	  bool                     paused;
1385	  bool                     stopping;
1386	  bool                     dma_active;
1387	  bool                     complete_sent;
1388	  int                      dma_ch;
1389	  FAR struct ap_buffer_s  *dma_apb;
1390	  uint32_t                 samprate;
1391	  uint8_t                  channels;
1392	  uint8_t                  bps;
1393	  uint8_t                  volume;
1394	};
