43	static int bk7258_devkit_pa_delay(unsigned int delay_ms)
44	{
45	  int ret;
46	
47	  /* Restart the complete short delay after a signal interruption.  This may
48	   * wait longer than requested, but never shortens the PA settling time.
49	   */
50	
51	  do
52	    {
53	      ret = nxsig_usleep(delay_ms * 1000);
54	    }
55	  while (ret == -EINTR);
56	
57	  if (ret < 0)
58	    {
59	      syslog(LOG_ERR, "BK7258 PA: delay failed: %d\n", ret);
60	    }
61	
62	  return ret;
63	}
