65	static void bk7258_devkit_pa_write(bool enable)
66	{
67	#if BOARD_AUDIO_PA_ACTIVE_HIGH
68	  bk7258_gpio_write(BOARD_AUDIO_PA_PIN, enable);
69	#else
70	  bk7258_gpio_write(BOARD_AUDIO_PA_PIN, !enable);
71	#endif
72	}
