74	static int bk7258_devkit_pa_init(FAR void *arg)
75	{
76	  int ret;
77	
78	  (void)arg;
79	
80	  /* Configure PA pin as output, initially low (PA disabled) */
81	
82	  ret = bk7258_gpio_config_output(BOARD_AUDIO_PA_PIN,
83	                                  !BOARD_AUDIO_PA_ACTIVE_HIGH);
84	  if (ret < 0)
85	    {
86	      syslog(LOG_ERR, "BK7258 PA: failed to configure GPIO%d: %d\n",
87	             BOARD_AUDIO_PA_PIN, ret);
88	      return ret;
89	    }
90	
91	  syslog(LOG_INFO, "BK7258 PA: initialized GPIO%d (active-%s)\n",
92	         BOARD_AUDIO_PA_PIN,
93	         BOARD_AUDIO_PA_ACTIVE_HIGH ? "high" : "low");
94	
95	  return OK;
96	}
97	
98	static int bk7258_devkit_pa_enable(FAR void *arg)
99	{
100	  int ret;
101	
102	  (void)arg;
103	
104	  /* Keep the PA inactive unless both settling delays succeed. */
105	
106	  ret = bk7258_devkit_pa_delay(BOARD_AUDIO_PA_PRE_ENABLE_MS);
107	  if (ret < 0)
108	    {
109	      bk7258_devkit_pa_write(false);
110	      return ret;
111	    }
112	
113	  bk7258_devkit_pa_write(true);
114	
115	  ret = bk7258_devkit_pa_delay(BOARD_AUDIO_PA_POST_ENABLE_MS);
116	  if (ret < 0)
117	    {
118	      bk7258_devkit_pa_write(false);
119	      return ret;
120	    }
121	
122	  syslog(LOG_DEBUG, "BK7258 PA: enabled\n");
123	  return OK;
124	}
125	
126	static int bk7258_devkit_pa_disable(FAR void *arg)
127	{
128	  int post_ret;
129	  int pre_ret;
130	
131	  (void)arg;
132	
133	  /* Delay failures are diagnostic only.  Once this callback returns, the
134	   * safety-critical guarantee is that the PA GPIO has been driven inactive.
135	   */
136	
137	  pre_ret = bk7258_devkit_pa_delay(BOARD_AUDIO_PA_PRE_DISABLE_MS);
138	  bk7258_devkit_pa_write(false);
139	  post_ret = bk7258_devkit_pa_delay(BOARD_AUDIO_PA_POST_DISABLE_MS);
140	
141	  if (pre_ret < 0 || post_ret < 0)
142	    {
143	      syslog(LOG_ERR,
144	             "BK7258 PA: disable delay failed (pre=%d post=%d)\n",
145	             pre_ret, post_ret);
146	    }
147	
148	  syslog(LOG_DEBUG, "BK7258 PA: disabled\n");
149	  return OK;
150	}
