/* IDLE button legend, justified to a common left and right edge.
 *
 * LVGL v9 has no justify align, so each line is its own fixed-width label
 * centred inside the block, and the slack between that line's natural
 * width and the block width is spread into its letter spacing.  Integer px
 * letter spacing means one or two px of the slack may be left over; the
 * centre align splits it between the two edges so both stay flush within
 * half a pixel of the gutter. */
{
  int32_t w[IDLE_HINT_LINES];
  uint32_t glyphs[IDLE_HINT_LINES];
  int32_t block_w = 0;
  int i;

  for (i = 0; i < IDLE_HINT_LINES; i++)
    {
      const char *t = s_idle_hint_lines[i];

      glyphs[i] = utf8_glyph_count(t);
      w[i]      = lv_text_get_width(t, (uint32_t)strlen(t),
                                    &lv_font_misans_12_cjk, 0);
      if (w[i] > block_w) block_w = w[i];
    }

