 * (AP 的 /data 是 tmpfs,一重启就没了)。 */
static void cmd_set_wifi(int argc, char** argv)
{
    if (argc < 3) {
        printf("Usage: set_wifi <ssid> <passphrase>\n"
               "  Saves the credentials and connects now; net_reconnect reuses\n"
               "  them when the link drops.\n");
        return;
    }

#if defined(AI_AGENT_WIFI_CTRL)
    int ret;

    claw_config_set(AGENT_CFG_KEY_WIFI_SSID, argv[1]);
    claw_config_set(AGENT_CFG_KEY_WIFI_PASS, argv[2]);

    printf("Wi-Fi credentials saved for %s; connecting...\n", argv[1]);
    ret = wifi_ctrl_connect(argv[1], argv[2]);
    printf("wifi_ctrl_connect -> %d\n", ret);
#else
    printf("set_wifi is not available on this target (no BK7258 Wi-Fi control plane)\n");
#endif
}

/* 用保存的凭据重新关联。板子掉网后不需要重烧、不需要重启。 */
static void cmd_net_reconnect(void)
{
#if defined(AI_AGENT_WIFI_CTRL)
    char ssid[WLAN_CTRL_SSID_LEN] = { 0 };
    char pass[WLAN_CTRL_PASS_LEN] = { 0 };
    int ret;
