820	/*
821	 * Wrap src in single quotes for safe use inside a system() shell command.
822	 * Every embedded ' is replaced by the sequence '\'' so arbitrary SSID/PSK
823	 * strings (spaces, semicolons, ampersands, etc.) cannot break the command.
824	 * Returns 0 on success, -1 if buf is too small.
825	 */
826	static int shell_quote(const char* src, char* buf, size_t buf_size)
827	{
828	    size_t out = 0;
829	    if (buf_size < 3) return -1; /* need at least '' + NUL */
830	    buf[out++] = '\'';
831	    for (const char* p = src; *p; p++) {
832	        if (*p == '\'') {
833	            if (out + 4 >= buf_size) return -1;
834	            buf[out++] = '\'';
835	            buf[out++] = '\\';
836	            buf[out++] = '\'';
837	            buf[out++] = '\'';
838	        } else {
839	            if (out + 1 >= buf_size) return -1;
840	            buf[out++] = *p;
841	        }
842	    }
843	    if (out + 1 >= buf_size) return -1;
844	    buf[out++] = '\'';
845	    buf[out]   = '\0';
846	    return 0;
847	}
