231	  struct btn_pollevents_s pe;
232	  struct pollfd pfd;
233	  btn_buttonset_t supported;
234	  btn_buttonset_t last;
235	  bool have_baseline = false;
236	  int fd;
237	  int bit = ptt_button_bit();
238	
239	  (void)arg;
240	
241	  fd = open(devpath, O_RDONLY);
242	  if (fd < 0)
243	    {
244	      syslog(LOG_ERR, "[%s] open %s failed: %d\n", TAG, devpath, errno);
245	      return NULL;
246	    }
247	
248	  supported = 0;
249	  if (ioctl(fd, BTNIOC_SUPPORTED, (unsigned long)&supported) < 0)
250	    {
251	      syslog(LOG_ERR, "[%s] BTNIOC_SUPPORTED failed: %d\n", TAG, errno);
252	      close(fd);
253	      return NULL;
254	    }
255	
256	  if ((supported & (btn_buttonset_t)bit) == 0)
257	    {
258	      syslog(LOG_ERR, "[%s] button idx %d not in supported set 0x%08lx\n",
259	             TAG, CONFIG_AI_AGENT_PTT_BUTTON_IDX, (unsigned long)supported);
260	      close(fd);
261	      return NULL;
262	    }
263	
264	  /* Wake on both edges of our PTT button only. */
265	  pe.bp_press   = (btn_buttonset_t)bit;
266	  pe.bp_release = (btn_buttonset_t)bit;
267	  (void)ioctl(fd, BTNIOC_POLLEVENTS, (unsigned long)&pe);
268	
269	  pfd.fd     = fd;
270	  pfd.events = POLLIN;
271	  last       = 0;
272	
273	  syslog(LOG_INFO, "[%s] watching %s button %d (hold-to-talk)\n", TAG,
274	         devpath, CONFIG_AI_AGENT_PTT_BUTTON_IDX);
275	
276	  for (;;)
277	    {
278	      btn_buttonset_t cur;
279	      btn_buttonset_t change;
280	      ssize_t nread;
281	
282	      if (poll(&pfd, 1, -1) < 0)
283	        {
284	          if (errno == EINTR)
285	            {
286	              continue;
287	            }
288	          syslog(LOG_ERR, "[%s] poll failed: %d\n", TAG, errno);
289	          break;
290	        }
291	
292	      if ((pfd.revents & POLLIN) == 0)
293	        {
294	          continue;
295	        }
296	
297	      nread = read(fd, &cur, sizeof(cur));
298	      if (nread != (ssize_t)sizeof(cur))
299	        {
300	          continue;
301	        }
302	
303	      if (!have_baseline)
304	        {
305	          last = cur;
306	          have_baseline = true;
307	          continue;
308	        }
309	
310	      change = cur ^ last;
311	      if ((change & (btn_buttonset_t)bit) == 0)
312	        {
313	          last = cur;
314	          continue;  /* our button didn't change */
315	        }
316	
317	      if (cur & (btn_buttonset_t)bit)
318	        {
319	          ptt_on_press();
320	        }
321	      else
322	        {
323	          ptt_on_release();
324	        }
325	      last = cur;
326	    }
327	
328	  close(fd);
329	  return NULL;

