632	  (void)ret;
633	
634	  /* gesture_update must run every slice, not only when poll reports data:
635	   * the deferred TAP and the HOLD timer are deadlines, and skipping the
636	   * quiet slices pushed them to the next key event -- which is why a tap
637	   * printed only when something else was pressed afterwards.
638	   *
639	   * The level is sampled every slice for the same reason.  poll() only
640	   * shortens the wait; read() returns the live GPIO level, so a lost edge
641	   * heals within one slice.  Reading only on POLLIN left KEY4 "held" after
642	   * a PTT whose release edge never reached us, and its RELEASE then fired
643	   * on the next KEY1 tap during an approval (board log).
644	   */
645	
646	  n = read(s_fd, &set, sizeof(set));
647	  if (n == sizeof(set))
648	    {
649	      s_held = (uint32_t)set;
650	    }
651	
652	  /* Report an edge the interrupt path never delivered.  The upper half
653	   * debounces for 30 ms before notifying, so a short mismatch is normal;
654	   * only one that outlives 200 ms without POLLIN is a lost edge.
655	   */
656	
657	  if (ret > 0)
658	    {
659	      s_irq_held = s_held;
660	    }
661	
662	  if (s_held != s_irq_held)
663	    {
664	      if (!s_skew)
665	        {
666	          s_skew = true;
667	          s_skew_ms = now_ms();
668	        }
669	      else if (!s_skew_reported &&
670	               (uint32_t)(now_ms() - s_skew_ms) >= 200)
671	        {
672	          s_skew_reported = true;
673	          printf("[key] missed edge: irq=%lx level=%lx\n",
674	                 (unsigned long)s_irq_held, (unsigned long)s_held);
675	          key3_regs("missed edge");
676	        }
677	    }
678	  else
679	    {
680	      s_skew = false;
681	      s_skew_reported = false;
682	    }
683	
684	  gesture_update(now_ms());
685	}
