500	static void gesture_update(uint32_t now)
501	{
502	  uint32_t pressed = s_held & ~s_prev;
503	  uint32_t released = s_prev & ~s_held;
504	  unsigned int i;
505	
506	  /* COMBO: two or more keys down at once.  Fires once on the transition
507	   * and then suppresses the individual TAP/HOLD for every key that took
508	   * part -- otherwise pressing KEY1 then KEY2 would emit COMBO *and* a
509	   * stray KEY1 TAP when KEY1 is released.
510	   */
511	
512	  if (pressed != 0 && (s_held & (s_held - 1)) != 0 && s_combo_started == 0)
513	    {
514	      s_combo_started = s_held;
515	      gesture_fire(s_held, GESTURE_COMBO);
516	    }
517	
518	  for (i = 0; i < KEY_COUNT; i++)
519	    {
520	      uint32_t bit = KEY_BIT(i);
521	
522	      if ((pressed & bit) != 0)
523	        {
524	          s_down_ms[i] = now;
525	          s_hold_fired[i] = false;
526	
527	          /* Only keys that carry a press-and-hold binding emit the edge
528	           * pair.  Firing it for every key made each tap of KEY1/KEY2 log
529	           * "unmapped" for PRESS and RELEASE before the TAP that mattered
530	           * (board: "我都是单击").  TAP/HOLD/DOUBLE/COMBO keep their
531	           * unmapped diagnostic -- those are gestures a person can
532	           * discover by accident, these are not.
533	           */
534	
535	          if (keymap_lookup(bit, GESTURE_PRESS, NULL) != NULL)
536	            {
537	              gesture_fire(bit, GESTURE_PRESS);
538	            }
539	        }
540	
541	      if ((s_combo_started & bit) != 0)
542	        {
543	          /* Consumed by the combo: no single-key gesture for this press, and
544	           * a tap left over from an earlier press of the same key must go
545	           * too -- otherwise it fires after the combo and looks like a stray
546	           * KEY1 tap.
547	           */
548	
549	          s_tap_pending[i] = false;
550	          if ((released & bit) != 0)
551	            {
552	              s_combo_started &= ~bit;
553	            }
554	
555	          continue;
556	        }
557	
558	      /* A key bound to GESTURE_PRESS is a press-and-hold key: the whole
559	       * gesture is the edge pair, so TAP and HOLD must not also fire or
560	       * releasing the PTT key would answer a permission request.
561	       */
562	
563	      if (keymap_lookup(bit, GESTURE_PRESS, NULL) == NULL)
564	        {
565	          if ((s_held & bit) != 0 && !s_hold_fired[i] &&
566	              (uint32_t)(now - s_down_ms[i]) >= GESTURE_HOLD_MS)
567	            {
568	              s_hold_fired[i] = true;
569	              s_tap_pending[i] = false;
570	              gesture_fire(bit, GESTURE_HOLD);
571	            }
572	
573	          if ((released & bit) != 0 && !s_hold_fired[i])
574	            {
575	              gesture_fire(bit, GESTURE_TAP);
576	            }
577	        }
578	
579	      if ((released & bit) != 0 &&
580	          keymap_lookup(bit, GESTURE_RELEASE, NULL) != NULL)
581	        {
582	          gesture_fire(bit, GESTURE_RELEASE);
583	        }
