586	  /* Reset the combo only after the loop has seen every release edge.
587	   * Clearing it on s_held == 0 beforehand let the last key released skip
588	   * the suppression and emit a stray TAP.
589	   */
590	
591	  if (s_held == 0)
592	    {
593	      s_combo_started = 0;
594	    }
