398	 * payload = [tool\0hint\0]. */
399	int lvgl_ui_channel_set_approval(const char *tool, const char *hint)
400	{
401	  struct ui_rpmsg_msg m;
402	  size_t off = 0, tlen, hlen;
403	  int ret;
404	
405	  /* Guard against NULL — memcpy(dst, NULL, 0) is UB even at zero length. */
406	  const char *st = tool != NULL ? tool : "";
407	  const char *sh = hint != NULL ? hint : "";
408	
409	  memset(&m, 0, sizeof(m));
410	  m.op = UI_RPMSG_SET_APPROVAL;
411	
412	  tlen = strlen(st);
413	  hlen = strlen(sh);
414	  if (tlen + hlen + 2 > UI_RPMSG_MAX_PAYLOAD)
415	    {
416	      /* Truncate hint first, then tool, keeping both NUL-terminated. */
417	      size_t room = UI_RPMSG_MAX_PAYLOAD - 2;   /* 2 NULs */
418	      if (tlen > room)
419	        {
420	          tlen = room;
421	          hlen = 0;
422	        }
423	      else if (tlen + hlen > room)
424	        {
425	          hlen = room - tlen;
426	        }
427	    }
428	
429	  memcpy(m.payload + off, st, tlen); off += tlen;
430	  m.payload[off++] = '\0';
431	  memcpy(m.payload + off, sh, hlen); off += hlen;
432	  m.payload[off++] = '\0';
433	  m.payload_len = (uint16_t)off;
434	
435	  ret = ui_rpmsg_send(&m);
436	  if (ret < 0)
437	    {
438	      syslog(LOG_WARNING, "[%s] set_approval to CP failed: %d\n", TAG, ret);
