```c
/* Gerrit query for this poll: the configured query plus a last-updated
 * window.  Two reasons:
 *
 *  - The cursor could only compare change NUMBERS, so a new patch set on an
 *    existing change (the normal upload path) was invisible forever once a
 *    newer change had been reported.  A time window makes "updated since
 *    the previous poll" the real signal, and the id LRU below just keeps
 *    the overlapping windows from reporting the same change twice.
 *  - It also bounds the response: after a re-flash the old behaviour
 *    replayed the whole open-change backlog as 16 notices.
 *
 * `-age:` takes a relative age, so no timezone formatting is needed (this
 * image has no locale TZ).  The window is twice the poll interval so a
 * slow or skipped poll cannot drop an update.
 */
static void gerrit_poll_args(char *out, size_t out_sz)
{
    notify_src_cfg_t *c = &s_cfg[NOTIFY_SRC_GERRIT];
    int interval = c->interval_sec > 0 ? c->interval_sec : AGENT_NOTIFY_INTERVAL_SEC;
    int mins = (interval * 2 + 59) / 60 + 1;
    char qbuf[224];

    cJSON *args = cJSON_Parse(c->query_args);
    if (!args) args = cJSON_CreateObject();
    if (!args) { out[0] = '\0'; return; }

    cJSON *q = cJSON_GetObjectItem(args, "query");
    const char *base = (q && cJSON_IsString(q)) ? q->valuestring : GERRIT_DEFAULT_QUERY;
    snprintf(qbuf, sizeof(qbuf), "%s -age:%dmin", base, mins);

    cJSON_DeleteItemFromObject(args, "query");
    cJSON_AddStringToObject(args, "query", qbuf);
    if (!cJSON_GetObjectItem(args, "limit")) cJSON_AddNumberToObject(args, "limit", 50);

    char *j = cJSON_PrintUnformatted(args);
    if (j) { strlcpy(out, j, out_sz); free(j); }
    else out[0] = '\0';
    cJSON_Delete(args);
}
```

