     * traffic, so reject it rather than sanitising it. */
    if (strchr(prefix, '+') != NULL || strchr(prefix, '#') != NULL || strchr(config->device_id, '+') != NULL || strchr(config->device_id, '#') != NULL || strchr(config->device_id, '/') != NULL) {
