        return false;
    }

    strcpy(transport->host, config->host);
    strcpy(transport->device_id, config->device_id);
    snprintf(transport->port, sizeof(transport->port), "%s",
        (config->port != NULL && config->port[0] != '\0') ? config->port : "1883");
