function topicPart(value, name) {
  if (typeof value !== "string" || !value || value.includes("+") || value.includes("#")) {
    throw new TypeError(`${name} must be a non-empty MQTT topic path without wildcards`);
  }
  return value.replace(/^\/+|\/+$/g, "");
