75	#define JIRA_LRU_SIZE 64
76	static char s_jira_lru[JIRA_LRU_SIZE][24];
77	static int s_jira_lru_n = 0;
78	
79	/* Gerrit in-memory LRU of recently reported change numbers (not persisted).
80	 * The poll query is already bounded to "updated in the last few minutes";
81	 * the LRU only keeps the overlapping windows of consecutive polls from
82	 * reporting the same change twice. */
83	#define GERRIT_LRU_SIZE 64
84	static long s_gerrit_lru[GERRIT_LRU_SIZE];
85	static int s_gerrit_lru_n = 0;
86	
87	static bool gerrit_lru_seen(long id)
88	{
89	    for (int i = 0; i < s_gerrit_lru_n; i++) {
90	        if (s_gerrit_lru[i] == id) {
91	            return true;
92	        }
93	    }
94	    return false;
95	}
96	
97	static void gerrit_lru_add(long id)
98	{
99	    if (s_gerrit_lru_n < GERRIT_LRU_SIZE) {
100	        s_gerrit_lru[s_gerrit_lru_n++] = id;
101	    } else {
102	        /* ring: drop the oldest */
103	        memmove(s_gerrit_lru, s_gerrit_lru + 1,
104	                sizeof(s_gerrit_lru[0]) * (GERRIT_LRU_SIZE - 1));
105	        s_gerrit_lru[GERRIT_LRU_SIZE - 1] = id;
106	    }
107	}
