157	static void notify_load_cfg(void)
158	{
159	    /* Gerrit */
160	    notify_src_cfg_t *g = &s_cfg[NOTIFY_SRC_GERRIT];
161	    g->enabled = cfg_load_bool(NOTIFY_SRC_GERRIT, "enabled", true);
162	    cfg_load_str(NOTIFY_SRC_GERRIT, "server", g->server_name,
163	                 sizeof(g->server_name), "gerrit");
164	    cfg_load_str(NOTIFY_SRC_GERRIT, "tool", g->tool_query,
165	                 sizeof(g->tool_query), "gerrit.query_changes");
166	    /* Only the user's own changes.  The plain `status:open` query reported
167	     * every open change in the project — a poll could surface a dozen
168	     * unrelated subjects that kept replacing each other on the notice page.
169	     * `owner:` covers what we push, `reviewer:` covers review requests. */
170	    cfg_load_str(NOTIFY_SRC_GERRIT, "query_args", g->query_args,
171	                 sizeof(g->query_args),
172	                 "{\"query\":\"status:open (owner:zhangyi101@xiaomi.com OR "
173	                 "reviewer:zhangyi101@xiaomi.com)\",\"limit\":50}");
174	    g->interval_sec = cfg_load_int(NOTIFY_SRC_GERRIT, "interval_sec",
175	                                   AGENT_NOTIFY_INTERVAL_SEC);
176	    cfg_load_str(NOTIFY_SRC_GERRIT, "last_cursor", g->last_cursor,
177	                 sizeof(g->last_cursor), "0");
178	
179	    /* Jira */
180	    notify_src_cfg_t *j = &s_cfg[NOTIFY_SRC_JIRA];
181	    j->enabled = cfg_load_bool(NOTIFY_SRC_JIRA, "enabled", true);
182	    cfg_load_str(NOTIFY_SRC_JIRA, "server", j->server_name,
183	                 sizeof(j->server_name), "jira");
184	    cfg_load_str(NOTIFY_SRC_JIRA, "tool", j->tool_query,
185	                 sizeof(j->tool_query), "jira.jira_search");
186	    {
187	        /* Default JQL: the last hour of updates, as a RELATIVE date.
188	         *
189	         * Relative dates are evaluated by Jira at query time, so the window
190	         * slides with every poll.  The previous absolute timestamp was built
191	         * once at boot, which froze the window: anything updated after boot
192	         * could never match, so the Jira leg could only ever report pre-boot
193	         * history.
194	         *
195	         * A relative date also sidesteps the timezone entirely.  This image
196	         * has no CONFIG_LIBC_LOCALTIME (localtime_r() is a UTC alias), and a
197	         * UTC-formatted "YYYY-MM-DD HH:MM" is read by Jira as local time
198	         * (UTC+8), widening the window by 8h (measured: 595 issues).
199	         *
200	         * limit=10 keeps one poll at ~16KB of HTTP body / ~7.3KB of payload
201	         * (measured) — inside MCP_RESP_BUF_SIZE (64KB) and
202	         * AGENT_NOTIFY_JSON_BUF_SIZE (16KB) respectively. */
203	        /* …and only the user's own issues.  Without the assignee/reporter/
204	         * watcher filter every updated issue in every project the token can
205	         * see matched, so the notice page reported strangers' tickets. */
206	        snprintf(j->query_args, sizeof(j->query_args),
207	                 "{\"jql\":\"(assignee = \\\"zhangyi101@xiaomi.com\\\" OR "
208	                 "reporter = \\\"zhangyi101@xiaomi.com\\\" OR "
209	                 "watcher = \\\"zhangyi101@xiaomi.com\\\") AND "
210	                 "updated >= -1h ORDER BY updated DESC\","
211	                 "\"fields\":\"summary,status,priority,assignee\",\"limit\":10}");
212	    }
213	    j->interval_sec = cfg_load_int(NOTIFY_SRC_JIRA, "interval_sec",
214	                                   AGENT_NOTIFY_INTERVAL_SEC * 2);
215	    cfg_load_str(NOTIFY_SRC_JIRA, "last_cursor", j->last_cursor,
216	                 sizeof(j->last_cursor), "");
217	}
