247	/* ── Push a notification to the outbound bus ──────────────────── */
248	
249	static void push_notify(notify_source_t src, const char *key,
250	                        const char *summary)
251	{
252	    const char *title;
253	    uint32_t color;
254	    char body[512];  /* toast body (no prefix) */
255	    char text[576];  /* bus content (with prefix, for cli mirror / log) */
256	
257	    if (src == NOTIFY_SRC_GERRIT) {
258	        title = "Gerrit";
259	        color = AGENT_NOTIFY_GERRIT_COLOR;
260	        snprintf(body, sizeof(body), "#%s: %s", key, summary);
261	        snprintf(text, sizeof(text), "Gerrit %s", body);
262	    } else {
263	        title = "Jira";
264	        color = AGENT_NOTIFY_JIRA_COLOR;
265	        snprintf(body, sizeof(body), "%s: %s", key, summary);
266	        snprintf(text, sizeof(text), "Jira %s", body);
267	    }
268	
269	    /* Notification page, not a toast: the round panel is too small for a top
270	     * banner (the body was clipped).  The page holds a fixed 5 s window
271	     * (LVGL_UI_NOTICE_MS), any user key exits early, and the approval page
272	     * outranks it. */
273	    lvgl_ui_channel_show_notice(title, body, color);
274	
275	    agent_msg_t msg;
276	    memset(&msg, 0, sizeof(msg));
277	    strncpy(msg.channel, AGENT_CHAN_LVGL_NOTIFY, sizeof(msg.channel) - 1);
278	    strncpy(msg.chat_id, "notify", sizeof(msg.chat_id) - 1);
279	    msg.content = strdup(text);
280	    if (!msg.content) {
281	        syslog(LOG_ERR, "[%s] strdup notify failed\n", TAG);
282	        return;
283	    }
284	    if (message_bus_push_outbound(&msg) != OK) {
285	        syslog(LOG_WARNING, "[%s] outbound push failed (bus full?)\n", TAG);
286	        free(msg.content);
287	        return;
288	    }
289	    syslog(LOG_INFO, "[%s] notified %s %s\n", TAG, title, key);
290	}
