292	/* ── Gerrit dedup: extract new changes from query result ─────── */
293	
294	/* Text fallback: the onedev gateway's query_changes returns a plain text
295	 * summary whose lines look like "- 10365285: subject text".  Scan one
296	 * buffer line by line and notify for ids the LRU has not reported yet;
297	 * the query's -age: window is what makes a line "new" (a new patch set on
298	 * an existing change shows up with its old, smaller number). */
299	static void gerrit_scan_text(const char *text, notify_source_t src,
300	                             long *last_max, int *n_new)
301	{
302	    const char *p = text;
303	
304	    while (p && *p) {
305	        const char *eol = strchr(p, '\n');
306	        size_t len = eol ? (size_t)(eol - p) : strlen(p);
307	
308	        /* "- <digits>: subject" */
309	        if (len > 4 && p[0] == '-' && p[1] == ' ') {
310	            char *end = NULL;
311	            long id = strtol(p + 2, &end, 10);
312	            if (end && end != p + 2 && *end == ':' && end[1] == ' '
313	                && id > 0 && !gerrit_lru_seen(id)) {
314	                const char *subj = end + 2;
315	                size_t slen = len - (size_t)(subj - p);
316	                char key[24];
317	                char summary[256];
318	
319	                snprintf(key, sizeof(key), "%ld", id);
320	                snprintf(summary, sizeof(summary), "%.*s",
321	                         (int)(slen < sizeof(summary) - 1
322	                               ? slen : sizeof(summary) - 1), subj);
323	                /* Mark seen even when the per-poll cap skips the push, so
324	                 * a burst cannot turn into a flood on later polls. */
325	                gerrit_lru_add(id);
326	                if (*n_new < AGENT_NOTIFY_MAX_NEW) {
327	                    push_notify(src, key, summary);
328	                    (*n_new)++;
329	                }
330	                if (id > *last_max) {

330	                if (id > *last_max) {
331	                    *last_max = id;
332	                }
333	            }
334	        }
335	        p = eol ? eol + 1 : NULL;
336	    }
337	}
338	
339	static int gerrit_dedup(const char *json, notify_source_t src, int *n_new_out)
340	{
341	    /* mcp_client_execute returns result.content[0].text.  Two shapes seen:
342	     *  1. structured JSON (array of change objects with _number/subject),
343	     *  2. the onedev gateway's text summary wrapped as
344	     *     [{"type":"text","text":"- 123: ...\n- 124: ..."}].
345	     * Try the structured path first; if no item carried a numeric id,
346	     * fall back to scanning the text payloads. */
347	    long last_max = strtol(s_cfg[src].last_cursor, NULL, 10);
348	    int n_new = 0;
349	
350	    cJSON *root = cJSON_Parse(json);
351	    if (root) {
352	        cJSON *arr = root;
353	        if (cJSON_IsObject(root)) {
354	            arr = cJSON_GetArrayItem(root, 0);
355	            if (!cJSON_IsArray(arr)) {
356	                arr = cJSON_GetObjectItem(root, "changes");
357	                if (!cJSON_IsArray(arr)) {
358	                    arr = cJSON_GetObjectItem(root, "result");
359	                }
360	            }
361	        }
362	
363	        int n_struct = 0;
364	        if (cJSON_IsArray(arr)) {
365	            cJSON *item;
366	            cJSON_ArrayForEach(item, arr) {
367	                cJSON *num = cJSON_GetObjectItem(item, "_number");
368	                if (!num) num = cJSON_GetObjectItem(item, "number");
369	                if (!num) num = cJSON_GetObjectItem(item, "change_id");
370	                if (!num || !cJSON_IsNumber(num)) continue;
371	                n_struct++;
372	
373	                long id = (long)num->valuedouble;
374	                if (id <= 0 || gerrit_lru_seen(id)) continue;
375	
376	                cJSON *subj = cJSON_GetObjectItem(item, "subject");
377	                if (!subj) subj = cJSON_GetObjectItem(item, "summary");
378	                const char *summary = (subj && cJSON_IsString(subj))
379	                                      ? subj->valuestring : "(no subject)";
380	
381	                char key[24];
382	                snprintf(key, sizeof(key), "%ld", id);
383	                /* Mark seen even when the per-poll cap skips the push, so
384	                 * a burst cannot turn into a flood on later polls. */
385	                gerrit_lru_add(id);
386	                if (n_new < AGENT_NOTIFY_MAX_NEW) {
387	                    push_notify(src, key, summary);
388	                    n_new++;
389	                }
390	
391	                if (id > last_max) {
392	                    last_max = id;  /* status display only */
393	                }
394	            }
395	        }
396	
397	        /* No structured ids found -> the array is a text-content wrapper;
398	         * scan each item's "text" field for "- <id>: <subject>" lines. */
399	        if (n_struct == 0 && cJSON_IsArray(arr)) {
400	            cJSON *item;
401	            cJSON_ArrayForEach(item, arr) {
402	                cJSON *text = cJSON_GetObjectItem(item, "text");
403	                if (text && cJSON_IsString(text)) {
404	                    gerrit_scan_text(text->valuestring, src,
405	                                     &last_max, &n_new);
406	                }
407	            }
408	        } else if (n_struct == 0) {
409	            /* Bare string / other shape: try the raw buffer as text. */
410	            cJSON *text = (root && cJSON_IsString(root)) ? root : NULL;
411	            if (text) {
412	                gerrit_scan_text(text->valuestring, src, &last_max, &n_new);
413	            }
414	        }
415	
416	        cJSON_Delete(root);
417	    } else {
418	        /* Not JSON at all — treat the whole buffer as text output. */
419	        gerrit_scan_text(json, src, &last_max, &n_new);
420	    }
421	
422	    if (n_new > 0) {
423	        snprintf(s_cfg[src].last_cursor, sizeof(s_cfg[src].last_cursor),
424	                 "%ld", last_max);
425	        persist_cursor(src);
426	    }
427	
428	    *n_new_out = n_new;
429	    return 0;
430	}
