432	/* ── Jira dedup: extract new issues ────────────────────────────── */
433	
434	static int jira_dedup(const char *json, notify_source_t src, int *n_new_out)
435	{
436	    cJSON *root = cJSON_Parse(json);
437	    if (!root) return -1;
438	
439	    cJSON *arr = cJSON_GetObjectItem(root, "issues");
440	    if (!cJSON_IsArray(arr)) {
441	        arr = cJSON_GetArrayItem(root, 0);  /* maybe top-level array */
442	    }
443	    if (!cJSON_IsArray(arr)) {
444	        cJSON_Delete(root);
445	        return -1;
446	    }
447	
448	    int n_new = 0;
449	    cJSON *item;
450	    cJSON_ArrayForEach(item, arr) {
451	        cJSON *keyobj = cJSON_GetObjectItem(item, "key");
452	        if (!keyobj || !cJSON_IsString(keyobj)) continue;
453	        const char *key = keyobj->valuestring;
454	        if (jira_lru_seen(key)) continue;
455	
456	        cJSON *fields = cJSON_GetObjectItem(item, "fields");
457	        const char *summary = "(no summary)";
458	        /* jira_search with a "fields" argument returns the requested fields
459	         * inline on each issue (no "fields" wrapper); full-issue responses
460	         * nest them under "fields".  Accept both. */
