464	        }
465	        if (s && cJSON_IsString(s)) summary = s->valuestring;
466	
467	        /* Mark every issue seen (even past the cap) so a large backlog
468	         * is not re-scanned as new on the next poll; only the first
469	         * AGENT_NOTIFY_MAX_NEW issues pop a toast. */
470	        jira_lru_add(key);
