488	/* ── Gerrit poll query: configured query + last-updated window ─── */
489	
490	#define GERRIT_DEFAULT_QUERY \
491	    "status:open (owner:zhangyi101@xiaomi.com OR " \
492	    "reviewer:zhangyi101@xiaomi.com)"
493	
494	/* Append `-age:<N>min` to the configured query so the server returns only
495	 * changes whose last update falls inside the window; that is what makes a
496	 * new patch set on an existing change a notification event.  `-age:` takes
497	 * a relative age evaluated by Gerrit itself, so the device clock and this
498	 * image's missing locale TZ cannot skew the window.  Twice the poll
499	 * interval (+1 min) tolerates a slow or skipped poll without dropping an
500	 * update; the id LRU absorbs the overlap. */
501	static void gerrit_poll_args(char *out, size_t out_sz)
502	{
503	    notify_src_cfg_t *c = &s_cfg[NOTIFY_SRC_GERRIT];
504	    int interval = c->interval_sec > 0 ? c->interval_sec
505	                                       : AGENT_NOTIFY_INTERVAL_SEC;
506	    int mins = (interval * 2 + 59) / 60 + 1;
507	    char qbuf[224];
508	
509	    cJSON *args = cJSON_Parse(c->query_args);
510	    if (args == NULL) {
511	        args = cJSON_CreateObject();
512	    }
513	    if (args == NULL) {
514	        out[0] = '\0';
515	        return;
516	    }
517	
518	    cJSON *q = cJSON_GetObjectItem(args, "query");
519	    const char *base = (q && cJSON_IsString(q)) ? q->valuestring
520	                                                : GERRIT_DEFAULT_QUERY;
521	    snprintf(qbuf, sizeof(qbuf), "%s -age:%dmin", base, mins);
522	
523	    cJSON_DeleteItemFromObject(args, "query");
524	    cJSON_AddStringToObject(args, "query", qbuf);
525	    if (cJSON_GetObjectItem(args, "limit") == NULL) {
526	        cJSON_AddNumberToObject(args, "limit", 50);
527	    }
528	
529	    char *j = cJSON_PrintUnformatted(args);
530	    if (j != NULL) {
531	        strlcpy(out, j, out_sz);
532	        free(j);
533	    } else {
534	        out[0] = '\0';
535	    }
536	    cJSON_Delete(args);
537	}
