540	
541	static void poll_one_source(notify_source_t src)
542	{
543	    notify_src_cfg_t *c = &s_cfg[src];
544	    if (!c->enabled || c->server_name[0] == '\0' || c->tool_query[0] == '\0') {
545	        return;
546	    }
547	
548	    char *buf = (char *)malloc(AGENT_NOTIFY_JSON_BUF_SIZE);
549	    if (!buf) {
550	        strlcpy(s_last_err, "alloc failed", sizeof(s_last_err));
551	        return;
552	    }
553	    buf[0] = '\0';
554	
555	    /* Gerrit polls through a freshly built time-windowed query; every other
556	     * source uses its configured args verbatim. */
557	    char gerrit_args[320];
558	    const char *args = c->query_args;
559	    if (src == NOTIFY_SRC_GERRIT) {
560	        gerrit_poll_args(gerrit_args, sizeof(gerrit_args));
561	        if (gerrit_args[0] != '\0') {
562	            args = gerrit_args;
563	        }
564	    }
565	
566	    syslog(LOG_INFO, "[%s] polling %s (%s)\n", TAG, c->server_name, c->tool_query);
567	    syslog(LOG_INFO, "[%s] %s args: %s\n", TAG, c->server_name, args);
568	
569	    int rc = mcp_client_execute(c->tool_query, args,
570	                                buf, AGENT_NOTIFY_JSON_BUF_SIZE);
571	    if (rc != OK && strstr(buf, "not discovered")) {
572	        /* Self-heal: if the boot-time discover failed (network race or a
573	         * transient gateway error), the tool table stays empty and every
574	         * poll fails forever.  Re-discover now — the poll interval already
575	         * rate-limits this — and retry once. */
576	        syslog(LOG_WARNING, "[%s] %s tools missing, re-discovering\n",
577	               TAG, c->server_name);
578	        mcp_client_discover();
579	        buf[0] = '\0';
580	        rc = mcp_client_execute(c->tool_query, args,
581	                                buf, AGENT_NOTIFY_JSON_BUF_SIZE);
582	    }
583	    if (rc != OK) {
584	        snprintf(s_last_err, sizeof(s_last_err), "%s exec failed", c->server_name);
585	        syslog(LOG_WARNING, "[%s] %s poll failed: %.80s\n", TAG,
586	               c->server_name, buf);
587	        free(buf);
588	        return;
589	    }
590	
591	    int n_new = 0;
592	    int parse_rc;
593	    if (src == NOTIFY_SRC_GERRIT) {
594	        parse_rc = gerrit_dedup(buf, src, &n_new);
595	    } else {
596	        parse_rc = jira_dedup(buf, src, &n_new);
597	    }
598	
599	    if (parse_rc < 0) {
600	        snprintf(s_last_err, sizeof(s_last_err), "%s parse failed", c->server_name);
601	        syslog(LOG_WARNING, "[%s] %s result not a JSON array: %.80s\n",
602	               TAG, c->server_name, buf);
603	    } else {
604	        s_last_err[0] = '\0';
605	        s_last_new_count = n_new;
606	        syslog(LOG_INFO, "[%s] %s poll: %d new\n", TAG, c->server_name, n_new);
607	    }
608	
609	    s_last_poll_epoch = (int)time(NULL);
610	    free(buf);
611	}
