613	/* ── Polling thread ────────────────────────────────────────────── */
614	
615	static void *notify_thread(void *arg)
616	{
617	    (void)arg;
618	
619	    struct timespec next_due[NOTIFY_SRC_COUNT];
620	    clock_gettime(CLOCK_REALTIME, &next_due[NOTIFY_SRC_GERRIT]);
621	    /* stagger: gerrit polls first, jira 30s later */
622	    next_due[NOTIFY_SRC_JIRA] = next_due[NOTIFY_SRC_GERRIT];
623	    next_due[NOTIFY_SRC_JIRA].tv_sec += 30;
624	
625	    while (s_running) {
626	        /* find earliest next_due */
627	        struct timespec earliest = next_due[0];
628	        for (int i = 1; i < NOTIFY_SRC_COUNT; i++) {
629	            if (next_due[i].tv_sec < earliest.tv_sec ||
630	                (next_due[i].tv_sec == earliest.tv_sec &&
631	                 next_due[i].tv_nsec < earliest.tv_nsec)) {
632	                earliest = next_due[i];
633	            }
634	        }
635	
636	        pthread_mutex_lock(&s_mtx);
637	        pthread_cond_timedwait(&s_cond, &s_mtx, &earliest);
638	        pthread_mutex_unlock(&s_mtx);
639	
640	        if (!s_running) break;
641	
642	        time_t now = time(NULL);
643	        for (int i = 0; i < NOTIFY_SRC_COUNT; i++) {
644	            if (!s_cfg[i].enabled) continue;
645	            if (now < next_due[i].tv_sec) continue;
646	            poll_one_source((notify_source_t)i);
647	            next_due[i].tv_sec = now + s_cfg[i].interval_sec;
648	        }
649	    }
650	
651	    return NULL;
652	}
