class SerialTransport:
    """Writes agent-CLI lines to the console and reads the device back.

    The read half matters: without it the host can prove it wrote a line but
    not that the watch rendered it.  Only lines matching DEVICE_LINE are
    echoed, so the console's Wi-Fi/LLM chatter stays out of the log.

    The watch is on a USB cable that gets unplugged: every access goes through
    ``_serial()``, which reopens the port after an I/O error instead of
    leaving the watcher silently writing into a dead fd.
    """

    def __init__(self, port: str, baud: int, echo: bool = True):
        import serial  # pyserial; lazy so --help works without it

        self._serial_mod = serial
        self._port = port
        self._baud = baud
        self._ser = None
        self._lock = threading.Lock()
        self._stop = threading.Event()
        self._reader = None
        self._open()
        if echo:
            self._reader = threading.Thread(target=self._read_loop, daemon=True)

    def _open(self) -> None:
        self._ser = self._serial_mod.Serial(self._port, self._baud,
                                            timeout=0.2, write_timeout=2)

    def _serial(self):
        """Return an open port, reopening it if the last handle died."""
        if self._ser is None or not self._ser.is_open:
            try:
                self._open()
                log(f"serial reopened {self._port}")
            except Exception as exc:
                raise IOError(f"serial unavailable: {exc}") from exc
        return self._ser

    def start(self) -> None:
        if self._reader is not None:
            self._reader.start()

    def _read_loop(self) -> None:
        while not self._stop.is_set():
            try:
                with self._lock:
                    raw = self._serial().readline()
            except Exception as exc:
                log(f"serial read failed: {exc}")
                with self._lock:
                    self._drop()
                self._stop.wait(1.0)
                continue
            if not raw:
                continue
            text = raw.decode("utf-8", "replace").strip()
            if text and DEVICE_LINE.search(text):
                log(f"dev| {text[:160]}")

    def _drop(self) -> None:
        try:
            if self._ser is not None:
                self._ser.close()
        except Exception:
            pass
        self._ser = None

    def inject(self, source: str, key: str, summary: str) -> None:
        line = f"notify_inject {source} {key} {summary}\r\n"
        with self._lock:
            for attempt in (1, 2):
                try:
                    self._serial().write(line.encode("ascii", "replace"))
                    return
                except Exception as exc:
                    log(f"serial write failed ({attempt}): {exc}")
                    self._drop()
        raise IOError("serial write failed twice")

