void cif_free_cmd_buffer(uint8_t* buf)
{
    if(!buf)
    {
        CIF_LOGE("%s,Invalid buffer.\n",__func__);
        return;
    }
    else
    {
        uint32_t* pattern_addr = (uint32_t*)(buf - EVENT_HEAD_LEN);
        *pattern_addr = PATTERN_FREE;
    }
}

